@Test
public void testInit() {
    AbstractCli.init();
    String[] keywords = { AbstractCli.HOST_ARGS, AbstractCli.HELP_ARGS, AbstractCli.PORT_ARGS, AbstractCli.PASSWORD_ARGS, AbstractCli.USERNAME_ARGS, AbstractCli.ISO8601_ARGS, AbstractCli.MAX_PRINT_ROW_COUNT_ARGS };
    for (String keyword : keywords) {
