@Test
public void testEvenDistribution() {
    /* Construct input data */
    Map<Integer, TDataNodeConfiguration> availableDataNodeMap = new ConcurrentHashMap<>();
    Map<Integer, Long> freeSpaceMap = new ConcurrentHashMap<>();
    Random random = new Random();
    // Set 6 DataNodes
    for (int i = 0; i < 6; i++) {
        availableDataNodeMap.put(i, new TDataNodeConfiguration().setLocation(new TDataNodeLocation().setDataNodeId(i)));
        freeSpaceMap.put(i, random.nextLong());
    }
    /* Allocate 6 RegionGroups */
    List<TRegionReplicaSet> allocatedRegionGroups = new ArrayList<>();
    for (int index = 0; index < 6; index++) {
        TRegionReplicaSet newRegionGroup = ALLOCATOR.generateOptimalRegionReplicasDistribution(availableDataNodeMap, freeSpaceMap, allocatedRegionGroups, TEST_REPLICATION_FACTOR, new TConsensusGroupId(TConsensusGroupType.DataRegion, index));
        allocatedRegionGroups.add(newRegionGroup);
    }
    /* Check result */
    Map<Integer, AtomicInteger> regionCounter = new ConcurrentHashMap<>();
    allocatedRegionGroups.forEach(regionReplicaSet -> regionReplicaSet.getDataNodeLocations().forEach(dataNodeLocation -> regionCounter.computeIfAbsent(dataNodeLocation.getDataNodeId(), empty -> new AtomicInteger(0)).getAndIncrement()));
    // Each DataNode should have exactly 3 Regions since the all 18 Regions are distributed to 6
    // DataNodes evenly
    Assert.assertEquals(6, regionCounter.size());
    regionCounter.forEach((dataNodeId, regionCount) -> Assert.assertEquals(3, regionCount.get()));
}

@Test
public void testUnevenDistribution() {
    /* Construct input data */
    Map<Integer, TDataNodeConfiguration> availableDataNodeMap = new ConcurrentHashMap<>();
    // Set 4 DataNodes
    for (int i = 0; i < 4; i++) {
        availableDataNodeMap.put(i, new TDataNodeConfiguration().setLocation(new TDataNodeLocation().setDataNodeId(i)));
    }
    Map<Integer, Long> freeSpaceMap = new ConcurrentHashMap<>();
    freeSpaceMap.put(0, 20000331L);
    freeSpaceMap.put(1, 20000522L);
    freeSpaceMap.put(2, 666L);
    freeSpaceMap.put(3, 999L);
    /* Allocate the first RegionGroup */
    List<TRegionReplicaSet> allocatedRegionGroups = new ArrayList<>();
    TRegionReplicaSet newRegionGroup = ALLOCATOR.generateOptimalRegionReplicasDistribution(availableDataNodeMap, freeSpaceMap, allocatedRegionGroups, TEST_REPLICATION_FACTOR, new TConsensusGroupId(TConsensusGroupType.SchemaRegion, 0));
    allocatedRegionGroups.add(newRegionGroup);
    Set<Integer> dataNodeIdSet = new HashSet<>();
    newRegionGroup.getDataNodeLocations().forEach(dataNodeLocation -> dataNodeIdSet.add(dataNodeLocation.getDataNodeId()));
    // The result should be the 3 DataNodes who have the maximum free disk space
    Assert.assertTrue(dataNodeIdSet.contains(0));
    Assert.assertTrue(dataNodeIdSet.contains(1));
    Assert.assertTrue(dataNodeIdSet.contains(3));
    dataNodeIdSet.clear();
    /* Allocate the second RegionGroup */
    newRegionGroup = ALLOCATOR.generateOptimalRegionReplicasDistribution(availableDataNodeMap, freeSpaceMap, allocatedRegionGroups, TEST_REPLICATION_FACTOR, new TConsensusGroupId(TConsensusGroupType.SchemaRegion, 1));
    newRegionGroup.getDataNodeLocations().forEach(dataNodeLocation -> dataNodeIdSet.add(dataNodeLocation.getDataNodeId()));
    // The result should contain the DataNode-2 and
    // other 2 DataNodes who have the maximum free disk space
    Assert.assertTrue(dataNodeIdSet.contains(0));
    Assert.assertTrue(dataNodeIdSet.contains(1));
    Assert.assertTrue(dataNodeIdSet.contains(2));
}

@Test
public void optimalLeaderDistributionTest() {
    Map<TConsensusGroupId, TRegionReplicaSet> regionReplicaSetMap = new HashMap<>();
    Map<TConsensusGroupId, Integer> regionLeaderMap = new HashMap<>();
    Set<Integer> disabledDataNodeSet = new HashSet<>();
    Random random = new Random();
    // Build 9 RegionGroups in DataNodes 0~2
    for (int i = 0; i < 9; i++) {
        TConsensusGroupId regionGroupId = new TConsensusGroupId(TConsensusGroupType.DataRegion, i);
        TRegionReplicaSet regionReplicaSet = new TRegionReplicaSet(regionGroupId, Arrays.asList(new TDataNodeLocation().setDataNodeId(0), new TDataNodeLocation().setDataNodeId(1), new TDataNodeLocation().setDataNodeId(2)));
        regionReplicaSetMap.put(regionGroupId, regionReplicaSet);
        regionLeaderMap.put(regionGroupId, random.nextInt(3));
    }
    // Build 9 RegionGroups in DataNodes 3~5
    for (int i = 9; i < 18; i++) {
        TConsensusGroupId regionGroupId = new TConsensusGroupId(TConsensusGroupType.DataRegion, i);
        TRegionReplicaSet regionReplicaSet = new TRegionReplicaSet(regionGroupId, Arrays.asList(new TDataNodeLocation().setDataNodeId(3), new TDataNodeLocation().setDataNodeId(4), new TDataNodeLocation().setDataNodeId(5)));
        regionReplicaSetMap.put(regionGroupId, regionReplicaSet);
        regionLeaderMap.put(regionGroupId, 3 + random.nextInt(3));
    }
    Map<TConsensusGroupId, Integer> leaderDistribution = BALANCER.generateOptimalLeaderDistribution(regionReplicaSetMap, regionLeaderMap, disabledDataNodeSet);
    Map<Integer, AtomicInteger> leaderCounter = new ConcurrentHashMap<>();
    leaderDistribution.forEach((regionGroupId, leaderId) -> leaderCounter.computeIfAbsent(leaderId, empty -> new AtomicInteger(0)).getAndIncrement());
    // Each DataNode has exactly 3 leaders
    for (int i = 0; i < 6; i++) {
        Assert.assertEquals(3, leaderCounter.get(i).get());
    }
}

