@Test
public void optimalLeaderDistributionTest() {
    // Prepare Data
    List<TConsensusGroupId> regionGroupIds = new ArrayList<>();
    for (int i = 0; i < 3; i++) {
        regionGroupIds.add(new TConsensusGroupId(TConsensusGroupType.DataRegion, i));
    }
    List<TDataNodeLocation> dataNodeLocations = new ArrayList<>();
    for (int i = 0; i < 4; i++) {
        dataNodeLocations.add(new TDataNodeLocation().setDataNodeId(i));
    }
    List<TRegionReplicaSet> regionReplicaSets = new ArrayList<>();
    regionReplicaSets.add(new TRegionReplicaSet(regionGroupIds.get(0), Arrays.asList(dataNodeLocations.get(0), dataNodeLocations.get(1), dataNodeLocations.get(2))));
    regionReplicaSets.add(new TRegionReplicaSet(regionGroupIds.get(1), Arrays.asList(dataNodeLocations.get(0), dataNodeLocations.get(1), dataNodeLocations.get(3))));
    regionReplicaSets.add(new TRegionReplicaSet(regionGroupIds.get(2), Arrays.asList(dataNodeLocations.get(0), dataNodeLocations.get(2), dataNodeLocations.get(3))));
    // Prepare input parameters
    Map<TConsensusGroupId, TRegionReplicaSet> regionReplicaSetMap = new HashMap<>();
    regionReplicaSets.forEach(regionReplicaSet -> regionReplicaSetMap.put(regionReplicaSet.getRegionId(), regionReplicaSet));
    Map<TConsensusGroupId, Integer> regionLeaderMap = new HashMap<>();
    regionReplicaSets.forEach(regionReplicaSet -> regionLeaderMap.put(regionReplicaSet.getRegionId(), 0));
    Set<Integer> disabledDataNodeSet = new HashSet<>();
    disabledDataNodeSet.add(0);
    // Do balancing
    Map<TConsensusGroupId, Integer> leaderDistribution = BALANCER.generateOptimalLeaderDistribution(regionReplicaSetMap, regionLeaderMap, disabledDataNodeSet);
    // All RegionGroup got a leader
    Assert.assertEquals(3, leaderDistribution.size());
    // Each DataNode occurs exactly once
    Assert.assertEquals(3, new HashSet<>(leaderDistribution.values()).size());
    // MaxFlow is 3
    Assert.assertEquals(3, BALANCER.getMaximumFlow());
    // MinimumCost is 3(switch leader cost) + 3(load cost, 1 for each DataNode)
    Assert.assertEquals(3 + 3, BALANCER.getMinimumCost());
}

