/**
 * In this case shows the balance ability for big cluster.
 *
 * <p>i.e. Simulate 1500 RegionGroups and 300 DataNodes
 */
@Test
public void bigClusterTest() {
    final int regionGroupNum = 1500;
    final int dataNodeNum = 300;
    final int replicationFactor = 3;
    // The loadCost for each DataNode are the same
    int x = regionGroupNum / dataNodeNum;
    // i.e. formula of 1^2 + 2^2 + 3^2 + ...
    int loadCost = x * (x + 1) * (2 * x + 1) / 6;
    int dataNodeId = 0;
    Random random = new Random();
    Map<TConsensusGroupId, TRegionReplicaSet> regionReplicaSetMap = new HashMap<>();
    Map<TConsensusGroupId, Integer> regionLeaderMap = new HashMap<>();
    for (int i = 0; i < regionGroupNum; i++) {
        TConsensusGroupId regionGroupId = new TConsensusGroupId(TConsensusGroupType.DataRegion, i);
        int leaderId = (dataNodeId + random.nextInt(replicationFactor)) % dataNodeNum;
        TRegionReplicaSet regionReplicaSet = new TRegionReplicaSet();
        regionReplicaSet.setRegionId(regionGroupId);
        for (int j = 0; j < 3; j++) {
            regionReplicaSet.addToDataNodeLocations(new TDataNodeLocation().setDataNodeId(dataNodeId));
            dataNodeId = (dataNodeId + 1) % dataNodeNum;
        }
        regionReplicaSetMap.put(regionGroupId, regionReplicaSet);
        regionLeaderMap.put(regionGroupId, leaderId);
    }
    // Do balancing
    Map<TConsensusGroupId, Integer> leaderDistribution = BALANCER.generateOptimalLeaderDistribution(regionReplicaSetMap, regionLeaderMap, new HashSet<>());
    // All RegionGroup got a leader
    Assert.assertEquals(regionGroupNum, leaderDistribution.size());
    Map<Integer, AtomicInteger> leaderCounter = new ConcurrentHashMap<>();
    leaderDistribution.values().forEach(leaderId -> leaderCounter.computeIfAbsent(leaderId, empty -> new AtomicInteger(0)).getAndIncrement());
    // Every DataNode has leader
    Assert.assertEquals(dataNodeNum, leaderCounter.size());
    // Every DataNode has exactly regionGroupNum / dataNodeNum leaders
    leaderCounter.values().forEach(leaderNum -> Assert.assertEquals(regionGroupNum / dataNodeNum, leaderNum.get()));
    // MaxFlow is regionGroupNum
    Assert.assertEquals(regionGroupNum, BALANCER.getMaximumFlow());
    int minimumCost = BALANCER.getMinimumCost();
    Assert.assertTrue(minimumCost >= loadCost * dataNodeNum);
    // The number of RegionGroups who have switched leader
    int switchCost = minimumCost - loadCost * dataNodeNum;
    AtomicInteger switchCount = new AtomicInteger(0);
    regionLeaderMap.forEach((regionGroupId, originLeader) -> {
        if (!Objects.equals(originLeader, leaderDistribution.get(regionGroupId))) {
            switchCount.getAndIncrement();
        }
    });
    Assert.assertEquals(switchCost, switchCount.get());
    System.out.printf("MCF algorithm switch leader for %s times to construct a balanced leader distribution of 300 DataNodes and 1500 RegionGroups cluster.%n", switchCost);
}

@Test
public void testGenLoadScoreGreedyRoutingPolicy() {
    /* Build TDataNodeLocations */
    List<TDataNodeLocation> dataNodeLocations = new ArrayList<>();
    for (int i = 0; i < 4; i++) {
        dataNodeLocations.add(new TDataNodeLocation(i, new TEndPoint("0.0.0.0", 6667 + i), new TEndPoint("0.0.0.0", 10730 + i), new TEndPoint("0.0.0.0", 10740 + i), new TEndPoint("0.0.0.0", 10760 + i), new TEndPoint("0.0.0.0", 10750 + i)));
    }
    /* Build nodeCacheMap */
    long currentTimeMillis = System.currentTimeMillis();
    Map<Integer, BaseNodeCache> nodeCacheMap = new HashMap<>();
    NodeStatus[] statuses = new NodeStatus[] { NodeStatus.Running, NodeStatus.Unknown, NodeStatus.Running, NodeStatus.ReadOnly };
    for (int i = 0; i < 4; i++) {
        nodeCacheMap.put(i, new DataNodeHeartbeatCache());
        nodeCacheMap.get(i).cacheHeartbeatSample(new NodeHeartbeatSample(new THeartbeatResp(currentTimeMillis, statuses[i].getStatus()), currentTimeMillis));
    }
    nodeCacheMap.values().forEach(BaseNodeCache::periodicUpdate);
    /* Get the loadScoreMap */
    Map<Integer, Long> loadScoreMap = new ConcurrentHashMap<>();
    nodeCacheMap.forEach((dataNodeId, heartbeatCache) -> loadScoreMap.put(dataNodeId, heartbeatCache.getLoadScore()));
    /* Build TRegionReplicaSet */
    TConsensusGroupId groupId1 = new TConsensusGroupId(TConsensusGroupType.SchemaRegion, 1);
    TRegionReplicaSet regionReplicaSet1 = new TRegionReplicaSet(groupId1, Arrays.asList(dataNodeLocations.get(1), dataNodeLocations.get(0)));
    TConsensusGroupId groupId2 = new TConsensusGroupId(TConsensusGroupType.DataRegion, 2);
    TRegionReplicaSet regionReplicaSet2 = new TRegionReplicaSet(groupId2, Arrays.asList(dataNodeLocations.get(2), dataNodeLocations.get(3)));
    /* Check result */
    Map<TConsensusGroupId, TRegionReplicaSet> result = new GreedyPriorityBalancer().generateOptimalRoutePriority(Arrays.asList(regionReplicaSet1, regionReplicaSet2), new HashMap<>(), loadScoreMap);
    Assert.assertEquals(2, result.size());
    TRegionReplicaSet result1 = result.get(groupId1);
    for (int i = 0; i < 2; i++) {
        Assert.assertEquals(dataNodeLocations.get(i), result1.getDataNodeLocations().get(i));
    }
    TRegionReplicaSet result2 = result.get(groupId2);
    for (int i = 3; i < 4; i++) {
        Assert.assertEquals(dataNodeLocations.get(i), result2.getDataNodeLocations().get(i - 2));
    }
}

@Test
public void testGenRealTimeRoutingPolicy() {
    // Build TDataNodeLocations
    List<TDataNodeLocation> dataNodeLocations = new ArrayList<>();
    for (int i = 0; i < 6; i++) {
        dataNodeLocations.add(new TDataNodeLocation(i, new TEndPoint("0.0.0.0", 6667 + i), new TEndPoint("0.0.0.0", 10730 + i), new TEndPoint("0.0.0.0", 10740 + i), new TEndPoint("0.0.0.0", 10760 + i), new TEndPoint("0.0.0.0", 10750 + i)));
    }
    // Build nodeCacheMap
    long currentTimeMillis = System.currentTimeMillis();
    Map<Integer, BaseNodeCache> nodeCacheMap = new HashMap<>();
    for (int i = 0; i < 6; i++) {
        nodeCacheMap.put(i, new DataNodeHeartbeatCache());
        if (i != 2 && i != 5) {
            nodeCacheMap.get(i).cacheHeartbeatSample(new NodeHeartbeatSample(new THeartbeatResp(currentTimeMillis, NodeStatus.Running.getStatus()), currentTimeMillis));
        }
    }
    nodeCacheMap.values().forEach(BaseNodeCache::periodicUpdate);
    // Get the loadScoreMap
    Map<Integer, Long> loadScoreMap = new ConcurrentHashMap<>();
    nodeCacheMap.forEach((dataNodeId, heartbeatCache) -> loadScoreMap.put(dataNodeId, heartbeatCache.getLoadScore()));
    // Build TRegionReplicaSet
    TConsensusGroupId groupId1 = new TConsensusGroupId(TConsensusGroupType.SchemaRegion, 1);
    TRegionReplicaSet regionReplicaSet1 = new TRegionReplicaSet(groupId1, Arrays.asList(dataNodeLocations.get(2), dataNodeLocations.get(1), dataNodeLocations.get(0)));
    TConsensusGroupId groupId2 = new TConsensusGroupId(TConsensusGroupType.DataRegion, 2);
    TRegionReplicaSet regionReplicaSet2 = new TRegionReplicaSet(groupId2, Arrays.asList(dataNodeLocations.get(5), dataNodeLocations.get(4), dataNodeLocations.get(3)));
    List<TRegionReplicaSet> regionReplicaSets = Arrays.asList(regionReplicaSet1, regionReplicaSet2);
    // Build leaderMap
    Map<TConsensusGroupId, Integer> leaderMap = new HashMap<>();
    leaderMap.put(groupId1, 1);
    leaderMap.put(groupId2, 4);
    // Check result
    Map<TConsensusGroupId, TRegionReplicaSet> result = new LeaderPriorityBalancer().generateOptimalRoutePriority(regionReplicaSets, leaderMap, loadScoreMap);
    TRegionReplicaSet result1 = result.get(groupId1);
    // Leader first
    Assert.assertEquals(dataNodeLocations.get(1), result1.getDataNodeLocations().get(0));
    // The others will be sorted by loadScore
    Assert.assertEquals(dataNodeLocations.get(0), result1.getDataNodeLocations().get(1));
    Assert.assertEquals(dataNodeLocations.get(2), result1.getDataNodeLocations().get(2));
    TRegionReplicaSet result2 = result.get(groupId2);
    // Leader first
    Assert.assertEquals(dataNodeLocations.get(4), result2.getDataNodeLocations().get(0));
    // The others will be sorted by loadScore
    Assert.assertEquals(dataNodeLocations.get(3), result2.getDataNodeLocations().get(1));
    Assert.assertEquals(dataNodeLocations.get(5), result2.getDataNodeLocations().get(2));
}

