    TConsensusGroupId dataRegionGroupId = new TConsensusGroupId(DataRegion, 0);
    TRegionReplicaSet schemaRegionSet = new TRegionReplicaSet(schemaRegionGroupId, Collections.singletonList(dataNodeLocation0));
    TRegionReplicaSet dataRegionSet = new TRegionReplicaSet(dataRegionGroupId, Collections.singletonList(dataNodeLocation1));
    // to test the equals method of Map<TConsensusGroupId, TRegionReplicaSet>
    Map<TConsensusGroupId, TRegionReplicaSet> failedRegions0 = new HashMap<TConsensusGroupId, TRegionReplicaSet>() {

        {
            put(dataRegionGroupId, dataRegionSet);
            put(schemaRegionGroupId, schemaRegionSet);
        }
    };
    Map<TConsensusGroupId, TRegionReplicaSet> failedRegions1 = new HashMap<TConsensusGroupId, TRegionReplicaSet>() {

        {
            put(schemaRegionGroupId, schemaRegionSet);
            put(dataRegionGroupId, dataRegionSet);
        }
    };
