        assertEquals(procedure0.hashCode(), procedure1.hashCode());
        CreateRegionGroupsProcedure procedure2 = (CreateRegionGroupsProcedure) ProcedureFactory.getInstance().create(ByteBuffer.wrap(byteArrayOutputStream.getBuf()));
        assertEquals(procedure0, procedure2);
        assertEquals(procedure0.hashCode(), procedure2.hashCode());
    } catch (IOException e) {
        fail();
    }
}

