@Test
public void testGZIPCompression() throws Exception {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.name WITH DATATYPE=TEXT");
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.age WITH DATATYPE=INT32, ENCODING=RLE, COMPRESSOR = GZIP");
        statement.execute("insert into root.ln.wf01.wt01(timestamp,name,age) values(1000,'zhang',10)");
        statement.execute("flush");
        ResultSet r1 = statement.executeQuery("select * from root.ln.wf01.wt01");
        r1.next();
        Assert.assertEquals("zhang", r1.getString(2));
        Assert.assertEquals(10, r1.getInt(3));
        statement.execute("insert into root.ln.wf01.wt01(timestamp,name,age) values(2000,'wang',20)");
        statement.execute("flush");
        statement.execute("insert into root.ln.wf01.wt01(timestamp,name,age) values(3000,'li',30)");
        ResultSet r2 = statement.executeQuery("select * from root.ln.wf01.wt01 where name = 'wang'");
        r2.next();
        Assert.assertEquals(20, r2.getInt(3));
        ResultSet r3 = statement.executeQuery("select * from root.ln.wf01.wt01 where name = 'li'");
        r3.next();
        Assert.assertEquals(30, r3.getInt(3));
        ResultSet r4 = statement.executeQuery("select sum(age) from root.ln.wf01.wt01");
        r4.next();
        double d = r4.getDouble(1);
        Assert.assertTrue(60.0 == d);
        // now we try to insert more values
        for (int i = 1; i <= 1000; i++) {
            String time = String.valueOf(i * 100);
            String values = String.valueOf(i * 10);
            statement.execute(String.format("insert into root.ln.wf01.wt01(timestamp,name,age) values(%s,'wang', %s)", time, values));
        }
        statement.execute("flush");
        ResultSet r5 = statement.executeQuery("select * from root.ln.wf01.wt01 where timestamp = 100000");
        r5.next();
        Assert.assertEquals(10000, r5.getInt(3));
    }
}

@Test
public void testCreateAndDropContinuousQuery() throws Exception {
    createTimeSeries(new String[] { "root.ln.wf01.wt01.ws01.temperature", "root.ln.wf01.wt01.ws02.temperature", "root.ln.wf01.wt02.ws01.temperature", "root.ln.wf01.wt02.ws02.temperature", "root.ln.wf02.wt01.ws01.temperature", "root.ln.wf02.wt01.ws02.temperature", "root.ln.wf02.wt02.ws01.temperature", "root.ln.wf02.wt02.ws02.temperature" });
    statement.execute("CREATE CONTINUOUS QUERY cq1 " + "BEGIN SELECT max_value(temperature) INTO temperature_max FROM root.ln.*.*.* " + "GROUP BY time(1s) END");
    statement.execute("CREATE CONTINUOUS QUERY cq2 " + "BEGIN SELECT avg(temperature) INTO temperature_cnt FROM root.ln.wf01.*.* " + " GROUP BY time(1s), level=3 END");
    statement.execute("CREATE CONTINUOUS QUERY cq3 " + "RESAMPLE EVERY 2s FOR 2s " + "BEGIN SELECT min_value(temperature) INTO temperature_avg FROM root.ln.wf01.*.* " + "GROUP BY time(1s), level=2 END");
    statement.execute("DROP CONTINUOUS QUERY cq1");
    statement.execute("DROP CONTINUOUS QUERY cq2");
    checkShowContinuousQueriesResult(new String[] { "cq3" });
    statement.close();
    connection.close();
    EnvironmentUtils.shutdownDaemon();
    EnvironmentUtils.stopDaemon();
    setUp();
    checkShowContinuousQueriesResult(new String[] { "cq3" });
    try {
        statement.execute("CREATE CONTINUOUS QUERY cq3 " + "RESAMPLE EVERY 2s FOR 2s " + "BEGIN SELECT avg(temperature) INTO temperature_avg FROM root.ln.wf01.*.* " + "GROUP BY time(1s), level=2 END");
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("already exists"));
    }
    try {
        statement.execute("DROP CONTINUOUS QUERY cq1");
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("not exist"));
    }
    statement.execute("CREATE CONTINUOUS QUERY cq1 " + "BEGIN SELECT sum(temperature) INTO temperature_max FROM root.ln.*.*.* " + "GROUP BY time(1s) END");
    statement.execute("CREATE CONTINUOUS QUERY cq2 " + "BEGIN SELECT avg(temperature) INTO temperature_cnt FROM root.ln.wf01.*.* " + " GROUP BY time(1s), level=3 END");
    checkShowContinuousQueriesResult(new String[] { "cq3", "cq1", "cq2" });
    statement.execute("DROP CONTINUOUS QUERY cq1");
    statement.execute("DROP CONTINUOUS QUERY cq2");
    statement.execute("DROP CONTINUOUS QUERY cq3");
}

