    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        boolean hasResultSet = statement.execute("select * from root.vehicle.** disable align");
        Assert.assertTrue(hasResultSet);
        try (ResultSet resultSet = statement.getResultSet()) {
            ResultSetMetaData resultSetMetaData = resultSet.getMetaData();
            List<Integer> actualIndexToExpectedIndexList = checkHeader(resultSetMetaData, "Timeroot.vehicle.d0.s0,root.vehicle.d0.s0," + "Timeroot.vehicle.d0.s1,root.vehicle.d0.s1," + "Timeroot.vehicle.d0.s2,root.vehicle.d0.s2," + "Timeroot.vehicle.d0.s3,root.vehicle.d0.s3," + "Timeroot.vehicle.d0.s4,root.vehicle.d0.s4," + "Timeroot.vehicle.d1.s0,root.vehicle.d1.s0,", new int[] { Types.INTEGER, Types.BIGINT, Types.FLOAT, Types.VARCHAR, Types.BOOLEAN, Types.INTEGER });
            int cnt = 0;
            while (resultSet.next()) {
                String[] expectedStrings = retArray[cnt].split(",");
                StringBuilder expectedBuilder = new StringBuilder();
                StringBuilder actualBuilder = new StringBuilder();
                for (int i = 1; i <= resultSetMetaData.getColumnCount(); i++) {
                    actualBuilder.append(resultSet.getString(i)).append(",");
                    expectedBuilder.append(expectedStrings[actualIndexToExpectedIndexList.get(i - 1)]).append(",");
