@Test
public void testCreateTimeSeriesWithoutEncoding() throws SQLException {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.name WITH DATATYPE=TEXT");
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.age WITH DATATYPE=INT32, ENCODING=RLE");
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.salary WITH DATATYPE=INT64");
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.score WITH DATATYPE=FLOAT");
        statement.execute("CREATE TIMESERIES root.ln.wf01.wt01.grade WITH DATATYPE=DOUBLE");
        ResultSet nameRs = statement.executeQuery("SHOW TIMESERIES root.ln.wf01.wt01.name");
        nameRs.next();
        Assert.assertTrue(TSEncoding.PLAIN.name().equalsIgnoreCase(nameRs.getString(5)));
        ResultSet ageRs = statement.executeQuery("SHOW TIMESERIES root.ln.wf01.wt01.age");
        ageRs.next();
        Assert.assertTrue(TSEncoding.RLE.name().equalsIgnoreCase(ageRs.getString(5)));
        ResultSet salaryRs = statement.executeQuery("SHOW TIMESERIES root.ln.wf01.wt01.salary");
        salaryRs.next();
        Assert.assertTrue(TSEncoding.RLE.name().equalsIgnoreCase(salaryRs.getString(5)));
        ResultSet scoreRs = statement.executeQuery("SHOW TIMESERIES root.ln.wf01.wt01.score");
        scoreRs.next();
        Assert.assertTrue(TSEncoding.GORILLA.name().equalsIgnoreCase(scoreRs.getString(5)));
        ResultSet gradeRs = statement.executeQuery("SHOW TIMESERIES root.ln.wf01.wt01.grade");
        gradeRs.next();
        Assert.assertTrue(TSEncoding.GORILLA.name().equalsIgnoreCase(gradeRs.getString(5)));
    }
}

@Test
public void selectAllTest() {
    String[] retArray = new String[] { "1,1,1", "2,2,2", "3,3,3", "4,4,4", "5,5,0", "6,6,1", "7,7,2", "8,8,3", "9,9,4" };
    String selectSql = "select * from root.**";
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement1 = connection.createStatement();
        Statement statement2 = connection.createStatement()) {
        statement1.setFetchSize(10);
        boolean hasResultSet1 = statement1.execute(selectSql);
        Assert.assertTrue(hasResultSet1);
        ResultSet resultSet1 = statement1.getResultSet();
        int cnt1 = 0;
        try {
            while (resultSet1.next() && cnt1 < 5) {
                StringBuilder builder = new StringBuilder();
                builder.append(resultSet1.getString(TestConstant.TIMESTAMP_STR)).append(",").append(resultSet1.getString("root.fans.d0.s0")).append(",").append(resultSet1.getString("root.fans.d0.s1"));
                Assert.assertEquals(retArray[cnt1], builder.toString());
                cnt1++;
            }
            statement2.setFetchSize(10);
            boolean hasResultSet2 = statement2.execute(selectSql);
            Assert.assertTrue(hasResultSet2);
            ResultSet resultSet2 = statement2.getResultSet();
            int cnt2 = 0;
            try {
                while (resultSet2.next()) {
                    StringBuilder builder = new StringBuilder();
                    builder.append(resultSet2.getString(TestConstant.TIMESTAMP_STR)).append(",").append(resultSet2.getString("root.fans.d0.s0")).append(",").append(resultSet2.getString("root.fans.d0.s1"));
                    Assert.assertEquals(retArray[cnt2], builder.toString());
                    cnt2++;
                }
            } finally {
                resultSet2.close();
            }
            Assert.assertEquals(9, cnt2);
            // use do-while instead of while because in the previous while loop, we have executed the
            // next function,
            // and the cursor has been moved to the next position, so we should fetch that value first.
            do {
                StringBuilder builder = new StringBuilder();
                builder.append(resultSet1.getString(TestConstant.TIMESTAMP_STR)).append(",").append(resultSet1.getString("root.fans.d0.s0")).append(",").append(resultSet1.getString("root.fans.d0.s1"));
                Assert.assertEquals(retArray[cnt1], builder.toString());
                cnt1++;
            } while (resultSet1.next());
            // Although the statement2 has the same sql as statement1, they shouldn't affect each other.
            // So the statement1's ResultSet should also have 9 rows in total.
            Assert.assertEquals(9, cnt1);
        } finally {
            resultSet1.close();
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

