            for (long timestamp = fileIndex * 512, end = fileIndex * 512 + 512; timestamp < end; ++timestamp) {
                for (int deviceIndex = 0; deviceIndex < 5; ++deviceIndex) {
                    statement.execute(String.format("insert into root.sg.d%d(time, s1, s2, s3) aligned values(%d, %d, %d, %d)", deviceIndex, timestamp, timestamp + 1, timestamp + 2, timestamp + 3));
                }
            }
            statement.execute("FLUSH");
        }
    }
    long deleteStart = 1024, deleteEnd = 2048;
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        for (int deviceIndex = 0; deviceIndex < 5; ++deviceIndex) {
            statement.execute("delete from root.sg.d" + deviceIndex + ".** where time >= " + deleteStart + " and time <= " + deleteEnd);
        }
        unload(statement);
    }
    RewriteTsFileTool.main(new String[] { "-h", "127.0.0.1", "-p", "6667", "-u", "root", "-pw", "root", "-f", tmpDir, "-rm", "s", "-ig" });
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        for (long timestamp = 0; timestamp < 512 * 5; ++timestamp) {
            for (int deviceIndex = 0; deviceIndex < 5; ++deviceIndex) {
                ResultSet resultSet = statement.executeQuery(String.format("select s1, s2, s3 from root.sg.d%d where time=%d", deviceIndex, timestamp));
                if (timestamp >= deleteStart && timestamp <= deleteEnd) {
                    Assert.assertFalse(resultSet.next());
                    continue;
                }
                Assert.assertTrue(resultSet.next());
                float s1Val = resultSet.getFloat("root.sg.d" + deviceIndex + ".s1");
                float s2Val = resultSet.getFloat("root.sg.d" + deviceIndex + ".s2");
                float s3Val = resultSet.getFloat("root.sg.d" + deviceIndex + ".s3");
                Assert.assertEquals(s1Val, timestamp + 1, 0.001);
                Assert.assertEquals(s2Val, timestamp + 2, 0.001);
                Assert.assertEquals(s3Val, timestamp + 3, 0.001);
                Assert.assertFalse(resultSet.next());
                resultSet.close();
            }
        }
    }
}

