@Test
public void testCreateTemplateAndCreateTimeseries() throws SQLException {
    // test create schema template repeatedly
    try {
        statement.execute("CREATE SCHEMA TEMPLATE t1 (s1 INT64 encoding=RLE compressor=SNAPPY, s2 INT32)");
    } catch (IoTDBSQLException e) {
        Assert.assertEquals(TSStatusCode.METADATA_ERROR.getStatusCode() + ": Duplicated template name: t1", e.getMessage());
    }
    // set schema template
    statement.execute("SET SCHEMA TEMPLATE t1 TO root.sg1.d1");
    statement.execute("SET SCHEMA TEMPLATE t2 TO root.sg1.d2");
    // test drop template which has been set
    try {
        statement.execute("DROP SCHEMA TEMPLATE t1");
    } catch (IoTDBSQLException e) {
        Assert.assertEquals(TSStatusCode.METADATA_ERROR.getStatusCode() + ": Template [t1] has been set on MTree, cannot be dropped now.", e.getMessage());
    }
    statement.execute("SHOW TIMESERIES root.sg1.**");
    try (ResultSet resultSet = statement.getResultSet()) {
        Assert.assertFalse(resultSet.next());
    }
    // create timeseries of schema template
    statement.execute("CREATE TIMESERIES OF SCHEMA TEMPLATE ON root.sg1.d1");
    statement.execute("CREATE TIMESERIES OF SCHEMA TEMPLATE ON root.sg1.d2");
    boolean hasResult = statement.execute("SHOW TIMESERIES root.sg1.**");
    Assert.assertTrue(hasResult);
    Set<String> expectedResult = new HashSet<>(Arrays.asList("root.sg1.d1.s1,INT64,RLE,SNAPPY", "root.sg1.d1.s2,DOUBLE,GORILLA,SNAPPY", "root.sg1.d2.s1,INT64,RLE,SNAPPY", "root.sg1.d2.s2,DOUBLE,GORILLA,SNAPPY"));
    try (ResultSet resultSet = statement.getResultSet()) {
        while (resultSet.next()) {
            String actualResult = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING);
            Assert.assertTrue(expectedResult.contains(actualResult));
            expectedResult.remove(actualResult);
        }
    }
    Assert.assertTrue(expectedResult.isEmpty());
    hasResult = statement.execute("SHOW DEVICES");
    Assert.assertTrue(hasResult);
    expectedResult = new HashSet<>(Arrays.asList("root.sg1.d1,false", "root.sg1.d2,true"));
    try (ResultSet resultSet = statement.getResultSet()) {
        while (resultSet.next()) {
            String actualResult = resultSet.getString(ColumnHeaderConstant.DEVICE) + "," + resultSet.getString(ColumnHeaderConstant.IS_ALIGNED);
            Assert.assertTrue(expectedResult.contains(actualResult));
            expectedResult.remove(actualResult);
        }
    }
    Assert.assertTrue(expectedResult.isEmpty());
    try {
        statement.execute("UNSET SCHEMA TEMPLATE t1 FROM root.sg1.d1");
    } catch (IoTDBSQLException e) {
        Assert.assertEquals(TSStatusCode.TEMPLATE_IS_IN_USE.getStatusCode() + ": Template is in use on root.sg1.d1", e.getMessage());
    }
}

