            while (set.next()) {
                cnt++;
                assertEquals(1, set.getLong("root.demo.d1.s3"));
            }
            assertEquals(1, cnt);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
