@Test
public void testVersionPersist() throws SQLException {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("CREATE DATABASE root.versionTest1");
        statement.execute("CREATE DATABASE root.versionTest2");
        statement.execute("CREATE TIMESERIES root.versionTest1.s0" + " WITH DATATYPE=INT32,ENCODING=PLAIN");
        statement.execute("CREATE TIMESERIES root.versionTest2.s0" + " WITH DATATYPE=INT32,ENCODING=PLAIN");
        // insert and flush enough times to make the version file persist
        for (int i = 0; i < SimpleFileVersionController.getSaveInterval() + 1; i++) {
            statement.execute(String.format("INSERT INTO root.versionTest1(timestamp, s0) VALUES (%d, %d)", i * 100, i));
            statement.execute("FLUSH");
            statement.execute("MERGE");
        }
    }
}

