@Test
public void testConflictNodeRegistration() throws ClientManagerException, InterruptedException, TException, IOException {
    /* Test ConfigNode conflict register */
    // Construct a ConfigNodeWrapper that conflicts in consensus port with an existed one.
    ConfigNodeWrapper conflictConfigNodeWrapper = EnvFactory.getEnv().generateRandomConfigNodeWrapper();
    conflictConfigNodeWrapper.setConsensusPort(EnvFactory.getEnv().getConfigNodeWrapper(1).getConsensusPort());
    conflictConfigNodeWrapper.changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getConfigNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getConfigNodeCommonConfig(), null);
    // The registration request should be rejected since there exists conflict port
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TConfigNodeRegisterReq req = ConfigNodeTestUtils.generateTConfigNodeRegisterReq(TEST_CLUSTER_NAME, conflictConfigNodeWrapper);
        req.getClusterParameters().setConfigNodeConsensusProtocolClass(testConsensusProtocolClass);
        TConfigNodeRegisterResp resp = client.registerConfigNode(req);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), resp.getStatus().getCode());
    }
    // The confignode-system.properties file should be empty before register
    File systemProperties = new File(conflictConfigNodeWrapper.getSystemPropertiesPath());
    Assert.assertFalse(systemProperties.exists());
    // The confignode-system.properties file should remain empty since the registration will fail
    EnvFactory.getEnv().registerNewConfigNode(conflictConfigNodeWrapper, false);
    Assert.assertFalse(systemProperties.exists());
    /* Construct a DataNodeWrapper that conflicts with an existed one. */
    // Construct a DataNodeWrapper that conflicts in internal port with an existed one.
    DataNodeWrapper conflictDataNodeWrapper = EnvFactory.getEnv().generateRandomDataNodeWrapper();
    conflictDataNodeWrapper.setInternalPort(EnvFactory.getEnv().getDataNodeWrapper(0).getInternalPort());
    conflictDataNodeWrapper.changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getDataNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getDataNodeCommonConfig(), null);
    // The registration request should be rejected since there exists conflict port
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TDataNodeRegisterReq req = ConfigNodeTestUtils.generateTDataNodeRegisterReq(TEST_CLUSTER_NAME, conflictDataNodeWrapper);
        TDataNodeRegisterResp resp = client.registerDataNode(req);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), resp.getStatus().getCode());
    }
    // The system.properties file should be empty before register
    systemProperties = new File(conflictDataNodeWrapper.getSystemPropertiesPath());
    Assert.assertFalse(systemProperties.exists());
    // The system.properties file should remain empty since the registration will fail
    EnvFactory.getEnv().registerNewDataNode(conflictDataNodeWrapper, false);
    Assert.assertFalse(systemProperties.exists());
}

@Test
public void testIllegalNodeRestart() throws ClientManagerException, IOException, InterruptedException, TException {
    ConfigNodeWrapper registeredConfigNodeWrapper = EnvFactory.getEnv().getConfigNodeWrapper(1);
    DataNodeWrapper registeredDataNodeWrapper = EnvFactory.getEnv().getDataNodeWrapper(0);
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        /* Restart with error cluster name */
        TConfigNodeRestartReq configNodeRestartReq = ConfigNodeTestUtils.generateTConfigNodeRestartReq(ERROR_CLUSTER_NAME, 1, registeredConfigNodeWrapper);
        TSStatus configNodeRestartStatus = client.restartConfigNode(configNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), configNodeRestartStatus.getCode());
        Assert.assertTrue(configNodeRestartStatus.getMessage().contains("cluster are inconsistent"));
        TDataNodeRestartReq dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(ERROR_CLUSTER_NAME, 2, registeredDataNodeWrapper);
        TDataNodeRestartResp dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("cluster are inconsistent"));
        /* Restart with error NodeId */
        configNodeRestartReq = ConfigNodeTestUtils.generateTConfigNodeRestartReq(TEST_CLUSTER_NAME, 100, registeredConfigNodeWrapper);
        configNodeRestartStatus = client.restartConfigNode(configNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), configNodeRestartStatus.getCode());
        Assert.assertTrue(configNodeRestartStatus.getMessage().contains("whose nodeId="));
        dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(TEST_CLUSTER_NAME, 200, registeredDataNodeWrapper);
        dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("whose nodeId="));
        /* Restart an alive Node */
        int registeredConfigNodeId = -1;
        TShowClusterResp showClusterResp = client.showCluster();
        for (TConfigNodeLocation configNodeLocation : showClusterResp.getConfigNodeList()) {
            if (configNodeLocation.getConsensusEndPoint().getPort() == registeredConfigNodeWrapper.getConsensusPort()) {
                registeredConfigNodeId = configNodeLocation.getConfigNodeId();
                break;
            }
        }
        Assert.assertNotEquals(-1, registeredConfigNodeId);
        configNodeRestartReq = ConfigNodeTestUtils.generateTConfigNodeRestartReq(TEST_CLUSTER_NAME, registeredConfigNodeId, registeredConfigNodeWrapper);
        configNodeRestartStatus = client.restartConfigNode(configNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), configNodeRestartStatus.getCode());
        Assert.assertTrue(configNodeRestartStatus.getMessage().contains("exists an alive Node with the same nodeId"));
        int registeredDataNodeId = -1;
        showClusterResp = client.showCluster();
        for (TDataNodeLocation dataNodeLocation : showClusterResp.getDataNodeList()) {
            if (dataNodeLocation.getInternalEndPoint().getPort() == registeredDataNodeWrapper.getInternalPort()) {
                registeredDataNodeId = dataNodeLocation.getDataNodeId();
                break;
            }
        }
        Assert.assertNotEquals(-1, registeredDataNodeId);
        dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(TEST_CLUSTER_NAME, registeredDataNodeId, registeredDataNodeWrapper);
        dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("exists an alive Node with the same nodeId"));
        // Shutdown and check
        EnvFactory.getEnv().shutdownConfigNode(1);
        EnvFactory.getEnv().shutdownDataNode(0);
        EnvFactory.getEnv().ensureNodeStatus(Arrays.asList(EnvFactory.getEnv().getConfigNodeWrapper(1), EnvFactory.getEnv().getDataNodeWrapper(0)), Arrays.asList(NodeStatus.Unknown, NodeStatus.Unknown));
        /* Restart and updatePeer */
        // TODO: @Itami-sho, enable this test and delete it
        int originPort = registeredConfigNodeWrapper.getConsensusPort();
        registeredConfigNodeWrapper.setConsensusPort(-12345);
        configNodeRestartReq = ConfigNodeTestUtils.generateTConfigNodeRestartReq(TEST_CLUSTER_NAME, registeredConfigNodeId, registeredConfigNodeWrapper);
        configNodeRestartStatus = client.restartConfigNode(configNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), configNodeRestartStatus.getCode());
        Assert.assertTrue(configNodeRestartStatus.getMessage().contains("have been changed"));
        registeredConfigNodeWrapper.setConsensusPort(originPort);
        originPort = registeredDataNodeWrapper.getInternalPort();
        registeredDataNodeWrapper.setInternalPort(-12345);
        dataNodeRestartReq = ConfigNodeTestUtils.generateTDataNodeRestartReq(TEST_CLUSTER_NAME, registeredDataNodeId, registeredDataNodeWrapper);
        dataNodeRestartResp = client.restartDataNode(dataNodeRestartReq);
        Assert.assertEquals(TSStatusCode.REJECT_NODE_START.getStatusCode(), dataNodeRestartResp.getStatus().getCode());
        Assert.assertTrue(dataNodeRestartResp.getStatus().getMessage().contains("have been changed"));
        registeredDataNodeWrapper.setInternalPort(originPort);
        // Restart and check
        EnvFactory.getEnv().startConfigNode(1);
        EnvFactory.getEnv().startDataNode(0);
        EnvFactory.getEnv().ensureNodeStatus(Arrays.asList(EnvFactory.getEnv().getConfigNodeWrapper(1), EnvFactory.getEnv().getDataNodeWrapper(0)), Arrays.asList(NodeStatus.Running, NodeStatus.Running));
    }
}

