        TShowCQResp showCQResp = client.showCQ();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), showCQResp.getStatus().getCode());
        assertEquals(expectedCQEntries, new HashSet<>(showCQResp.cqList));
    }
}

@Test
public void testSnapshotTransfer() throws Exception {
    try (final Connection connection = EnvFactory.getEnv().getConnection();
        final Statement statement = connection.createStatement();
        final SyncConfigNodeIServiceClient configClient = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        statement.execute("CREATE DATABASE root.emma");
        statement.execute("CREATE TIMESERIES root.emma.william.ethereal WITH DATATYPE=INT32,ENCODING=PLAIN");
        // insert large amounts of data to trigger a snapshot
        for (int i = 0; i < snapshotMagic + 1; i++) {
            final String insert = String.format("INSERT INTO root.emma.william(timestamp, ethereal) values(%d, %d)", i, i);
            statement.execute(insert);
        }
        final TShowRegionResp result = configClient.showRegion(new TShowRegionReq());
        Assert.assertNotNull(result.getRegionInfoList());
        final Optional<TRegionInfo> dataRegionInfo = result.getRegionInfoList().stream().filter(info -> info.getConsensusGroupId().getType().equals(TConsensusGroupType.DataRegion)).findAny();
        Assert.assertTrue(dataRegionInfo.isPresent());
        final int dataNodeId = dataRegionInfo.get().getDataNodeId();
        final TDataNodeConfigurationResp locationResp = configClient.getDataNodeConfiguration(dataNodeId);
        Assert.assertNotNull(locationResp.getDataNodeConfigurationMap());
        // remove this datanode and the regions will be transferred to the other one
        final TDataNodeRemoveReq removeReq = new TDataNodeRemoveReq();
        final TDataNodeLocation location = locationResp.getDataNodeConfigurationMap().get(dataNodeId).getLocation();
        removeReq.setDataNodeLocations(Collections.singletonList(location));
        final TDataNodeRemoveResp removeResp = configClient.removeDataNode(removeReq);
        Assert.assertEquals(removeResp.getStatus().getCode(), TSStatusCode.SUCCESS_STATUS.getStatusCode());
        // insert new data to ensure that the data regions are properly functioning
        for (int i = 0; i < snapshotMagic + 1; i++) {
            final String insert = String.format("INSERT INTO root.emma.william(timestamp, ethereal) values (%d, %d)", i + snapshotMagic * 2, i + snapshotMagic * 2);
            statement.execute(insert);
        }
        final ResultSet readResult = statement.executeQuery("SELECT count(*) from root.emma.william");
        readResult.next();
        Assert.assertEquals(2 * (snapshotMagic + 1), readResult.getInt("count(root.emma.william.ethereal)"));
        EnvFactory.getEnv().registerNewConfigNode(true);
        final TShowRegionResp registerResult = configClient.showRegion(new TShowRegionReq());
        Assert.assertNotNull(result.getRegionInfoList());
        final long configNodeGroupCount = registerResult.getRegionInfoList().stream().filter(info -> info.getConsensusGroupId().getType().equals(TConsensusGroupType.ConfigNodeRegion)).count();
        Assert.assertEquals(4, configNodeGroupCount);
    }
}

@Test
public void testSetAndQueryStorageGroup() throws Exception {
    TSStatus status;
    final String sg0 = "root.sg0";
    final String sg1 = "root.sg1";
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // set StorageGroup0 by default values
        TSetStorageGroupReq setReq0 = new TSetStorageGroupReq(new TStorageGroupSchema(sg0));
        status = client.setStorageGroup(setReq0);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // set StorageGroup1 by specific values
        TSetStorageGroupReq setReq1 = new TSetStorageGroupReq(new TStorageGroupSchema(sg1).setTTL(1024L).setSchemaReplicationFactor(5).setDataReplicationFactor(5).setTimePartitionInterval(2048L));
        status = client.setStorageGroup(setReq1);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // test count all StorageGroups
        TCountStorageGroupResp countResp = client.countMatchedStorageGroups(Arrays.asList("root", "**"));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), countResp.getStatus().getCode());
        Assert.assertEquals(2, countResp.getCount());
        // test count one StorageGroup
        countResp = client.countMatchedStorageGroups(Arrays.asList("root", "sg0"));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), countResp.getStatus().getCode());
        Assert.assertEquals(1, countResp.getCount());
        // test query all StorageGroupSchemas
        TStorageGroupSchemaResp getResp = client.getMatchedStorageGroupSchemas(Arrays.asList("root", "**"));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), getResp.getStatus().getCode());
        Map<String, TStorageGroupSchema> schemaMap = getResp.getStorageGroupSchemaMap();
        Assert.assertEquals(2, schemaMap.size());
        TStorageGroupSchema storageGroupSchema = schemaMap.get(sg0);
        Assert.assertNotNull(storageGroupSchema);
        Assert.assertEquals(sg0, storageGroupSchema.getName());
        Assert.assertEquals(Long.MAX_VALUE, storageGroupSchema.getTTL());
        Assert.assertEquals(1, storageGroupSchema.getSchemaReplicationFactor());
        Assert.assertEquals(1, storageGroupSchema.getDataReplicationFactor());
        Assert.assertEquals(604800000, storageGroupSchema.getTimePartitionInterval());
        storageGroupSchema = schemaMap.get(sg1);
        Assert.assertNotNull(storageGroupSchema);
        Assert.assertEquals(sg1, storageGroupSchema.getName());
        Assert.assertEquals(1024L, storageGroupSchema.getTTL());
        Assert.assertEquals(5, storageGroupSchema.getSchemaReplicationFactor());
        Assert.assertEquals(5, storageGroupSchema.getDataReplicationFactor());
        Assert.assertEquals(2048L, storageGroupSchema.getTimePartitionInterval());
        // test fail by re-register
