            if (NodeStatus.Removing.getStatus().equals(nodeStatus)) {
                Assert.assertEquals(0, regionCount.get());
            } else if (NodeStatus.Running.getStatus().equals(nodeStatus)) {
                Assert.assertEquals(1, regionCount.get());
            } else {
                Assert.fail();
            }
        });
    }
}

