@Test
public void testDataPartitionInheritPolicy() throws Exception {
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TDataPartitionReq dataPartitionReq = new TDataPartitionReq();
        TDataPartitionTableResp dataPartitionTableResp;
        Map<String, Map<TSeriesPartitionSlot, TTimeSlotList>> partitionSlotsMap;
        for (int i = 0; i < storageGroupNum; i++) {
            String storageGroup = sg + i;
            for (int j = 0; j < testSeriesPartitionSlotNum; j += seriesPartitionBatchSize) {
                for (long k = 0; k < testTimePartitionSlotsNum; k += timePartitionBatchSize) {
                    partitionSlotsMap = ConfigNodeTestUtils.constructPartitionSlotsMap(storageGroup, j, j + seriesPartitionBatchSize, k, k + timePartitionBatchSize, testTimePartitionInterval);
                    // Let ConfigNode create DataPartition
                    dataPartitionReq.setPartitionSlotsMap(partitionSlotsMap);
                    for (int retry = 0; retry < 5; retry++) {
                        // Build new Client since it's unstable
                        try (SyncConfigNodeIServiceClient configNodeClient = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
                            dataPartitionTableResp = configNodeClient.getOrCreateDataPartitionTable(dataPartitionReq);
                            if (dataPartitionTableResp != null) {
                                break;
                            }
                        } catch (Exception e) {
                            // Retry sometimes in order to avoid request timeout
                            LOGGER.error(e.getMessage());
                            TimeUnit.SECONDS.sleep(1);
                        }
                    }
                }
            }
        }
        // Test DataPartition inherit policy
        TShowRegionResp showRegionResp = client.showRegion(new TShowRegionReq());
        showRegionResp.getRegionInfoList().forEach(regionInfo -> {
            // All Timeslots belonging to the same SeriesSlot are allocated to the same
            // DataRegionGroup
            Assert.assertEquals(regionInfo.getSeriesSlots() * testTimePartitionSlotsNum, regionInfo.getTimeSlots());
        });
    }
}

