@Test
public void testCQExecution1() {
    String insertTemplate = "INSERT INTO root.sg.d1(time, s1) VALUES (%d, %d) (%d, %d) (%d, %d) (%d, %d) (%d, %d) (%d, %d) (%d, %d) (%d, %d) (%d, %d) (%d, %d)";
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        long now = System.currentTimeMillis();
        long firstExecutionTime = now + 10_000;
        long startTime = firstExecutionTime - 3_000;
        statement.execute("create timeseries root.sg.d1.s1 WITH DATATYPE=INT64");
        statement.execute("create timeseries root.sg.d1.s1_max WITH DATATYPE=INT64");
        statement.execute(String.format(insertTemplate, startTime, 1, startTime + 500, 2, startTime + 1_000, 3, startTime + 1_500, 4, startTime + 2_000, 5, startTime + 2_500, 6, startTime + 3_000, 7, startTime + 3_500, 8, startTime + 4_000, 9, startTime + 4_500, 10));
        statement.execute("CREATE CONTINUOUS QUERY cq1\n" + "RESAMPLE EVERY 2s\n" + String.format("BOUNDARY %d\n", firstExecutionTime) + "BEGIN \n" + "  SELECT max_value(s1) \n" + "  INTO root.sg.d1(s1_max)\n" + "  FROM root.sg.d1\n" + "  GROUP BY(1s) \n" + "END");
        long targetTime = firstExecutionTime + 5_000;
        while (System.currentTimeMillis() - targetTime < 0) {
            TimeUnit.SECONDS.sleep(1);
        }
        long[] expectedTime = { startTime + 1_000, startTime + 2_000, startTime + 3_000, startTime + 4_000 };
        long[] expectedValue = { 4, 6, 8, 10 };
        try (ResultSet resultSet = statement.executeQuery("select s1_max from root.sg.d1")) {
            int cnt = 0;
            while (resultSet.next()) {
                assertEquals(expectedTime[cnt], resultSet.getLong(TIMESTAMP_STR));
                assertEquals(expectedValue[cnt], resultSet.getLong("root.sg.d1.s1_max"));
                cnt++;
            }
            assertEquals(expectedTime.length, cnt);
        } finally {
            statement.execute("DROP CQ cq1");
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

