@Test
public void illegalGrantRevokeUserTest() throws SQLException {
    try (Connection adminCon = EnvFactory.getEnv().getConnection();
        Statement adminStmt = adminCon.createStatement()) {
        adminStmt.execute("CREATE USER tempuser 'temppw'");
        try (Connection userCon = EnvFactory.getEnv().getConnection("tempuser", "temppw");
            Statement userStmt = userCon.createStatement()) {
            // grant a non-existing user
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("GRANT USER nulluser PRIVILEGES CREATE_DATABASE on root.a"));
            // grant a non-existing privilege
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("GRANT USER tempuser PRIVILEGES NOT_A_PRIVILEGE on root.a"));
            // duplicate grant
            adminStmt.execute("GRANT USER tempuser PRIVILEGES CREATE_USER on root.**");
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("GRANT USER tempuser PRIVILEGES CREATE_USER on root.**"));
            // grant on a illegal seriesPath
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("GRANT USER tempuser PRIVILEGES DELETE_TIMESERIES on a.b"));
            // grant admin
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("GRANT USER root PRIVILEGES DELETE_TIMESERIES on root.a.b"));
            // no privilege to grant
            Assert.assertThrows(SQLException.class, () -> userStmt.execute("GRANT USER tempuser PRIVILEGES DELETE_TIMESERIES on root.a.b"));
            // revoke a non-existing privilege
            adminStmt.execute("REVOKE USER tempuser PRIVILEGES CREATE_USER on root.**");
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("REVOKE USER tempuser PRIVILEGES CREATE_USER on root.**"));
            // revoke a non-existing user
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("REVOKE USER tempuser1 PRIVILEGES CREATE_USER on root.**"));
            // revoke on a illegal seriesPath
            Assert.assertThrows(SQLException.class, () -> adminStmt.execute("REVOKE USER tempuser PRIVILEGES DELETE_TIMESERIES on a.b"));
            // revoke admin
