@Ignore
public void testNestedWindowingFunctionExpressions() {
    final int[] windows = new int[] { 1, 2, 3, 100, 499, ITERATION_TIMES - 1, ITERATION_TIMES, ITERATION_TIMES + 1, ITERATION_TIMES + 13 };
    for (int window : windows) {
        String sqlStr = String.format("select time_window_counter(sin(d1.s1), '%s'='%s', '%s'='%s'), time_window_counter(sin(d1.s1), cos(d2.s2) / sin(d1.s1), d1.s2, '%s'='%s', '%s'='%s'), size_window_counter(cos(d2.s2), '%s'='%s', '%s'='%s'), size_window_counter(cos(d2.s2), cos(d2.s2), '%s'='%s', '%s'='%s') from root.vehicle", UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_TIME, UDFTestConstant.TIME_INTERVAL_KEY, window, UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_TIME, UDFTestConstant.TIME_INTERVAL_KEY, window, UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_SIZE, UDFTestConstant.WINDOW_SIZE_KEY, window, UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_SIZE, UDFTestConstant.WINDOW_SIZE_KEY, window);
        try (Connection connection = EnvFactory.getEnv().getConnection();
            Statement statement = connection.createStatement();
            ResultSet resultSet = statement.executeQuery(sqlStr)) {
            assertEquals(1 + 4, resultSet.getMetaData().getColumnCount());
            int count = 0;
            while (resultSet.next()) {
                assertEquals((long) count * window + 1, Long.parseLong(resultSet.getString(1)));
                double c2 = Double.parseDouble(resultSet.getString(2));
                double c3 = Double.parseDouble(resultSet.getString(3));
                double c4 = Double.parseDouble(resultSet.getString(4));
                double c5 = Double.parseDouble(resultSet.getString(5));
                ++count;
                assertEquals(((ITERATION_TIMES < count * window) ? window - (count * window - ITERATION_TIMES) : window), c2, 0);
                assertEquals(c2, c3, 0);
                assertEquals(c2, c4, 0);
                assertEquals(c2, c5, 0);
            }
            assertEquals(ITERATION_TIMES / window + (ITERATION_TIMES % window == 0 ? 0 : 1), count);
        } catch (SQLException throwable) {
            fail(throwable.getMessage());
        }
    }
}

