    }
}

@Test
public void testComplexExpression() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        ResultSet resultSet = statement.executeQuery("select ( s1 + 1 ) * 2 - 4 < ( s3 * 3 - 6) / 2 && ( s1 + 5 ) * 2 > s2 * 3 + 4 from root.sg.d1");
        int columnCount = resultSet.getMetaData().getColumnCount();
        assertEquals(1 + 1, columnCount);
        boolean bool;
        for (int i = 0; i < time.size(); ++i) {
            resultSet.next();
            bool = Boolean.parseBoolean(resultSet.getString(2));
            assertEquals((intValue.get(i) + 1) * 2 - 4 < (floatValue.get(i) * 3 - 6) / 2 && (intValue.get(i) + 5) * 2 > longValue.get(i) * 3 + 4, bool);
        }
    } catch (SQLException throwable) {
        fail(throwable.getMessage());
    }
}

@Test
public void testSchemaExpression() {
    String[] expressions = { "s1+s2", "-s1+s2", "-(s1+s3)", "!(s1>s2)", "-(-(s1))", "((s1+s2)*s3)", "-2+s1", "!true||s1>0", "-(-1)+s1", "sin(s1)+s1", "((s1+1)*2-1)%2+1.5+s2" };
    String[] completeExpressions = { "root.sg.d1.s1+root.sg.d1.s2", "-root.sg.d1.s1+root.sg.d1.s2", "-(root.sg.d1.s1+root.sg.d1.s3)", "!(root.sg.d1.s1>root.sg.d1.s2)", "-(-root.sg.d1.s1)", "(root.sg.d1.s1+root.sg.d1.s2)*root.sg.d1.s3", "-2+root.sg.d1.s1", "!true|root.sg.d1.s1>0", "-(-1)+root.sg.d1.s1", "sin(root.sg.d1.s1)+root.sg.d1.s1", "((root.sg.d1.s1+1)*2-1)%2+1.5+root.sg.d1.s2" };
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        ResultSet resultSet = statement.executeQuery(String.format("select %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s from root.sg.d1", expressions[0], expressions[1], expressions[2], expressions[3], expressions[4], expressions[5], expressions[6], expressions[7], expressions[8], expressions[9], expressions[10]));
        int columnCount = resultSet.getMetaData().getColumnCount();
        assertEquals(1 + expressions.length, columnCount);
        for (int i = 0; i < expressions.length; ++i) {
            assertEquals(completeExpressions[i], resultSet.getMetaData().getColumnName(i + 2).replace(" ", ""));
        }
    } catch (SQLException throwable) {
        fail(throwable.getMessage());
    }
}

