@Test
public void renameTest() {
    String[] ret1 = { "root.turbine.d1.s1,temperature,root.turbine,FLOAT,RLE,SNAPPY," + "{\"tag1\":\"v1\",\"tag2\":\"v2\"},{\"attr2\":\"v2\",\"attr1\":\"v1\"}" };
    String[] ret2 = { "root.turbine.d1.s1,temperature,root.turbine,FLOAT,RLE,SNAPPY," + "{\"tag2\":\"v2\",\"tagNew1\":\"v1\"},{\"attr2\":\"v2\",\"attr1\":\"v1\"}" };
    String sql = "create timeseries root.turbine.d1.s1(temperature) with datatype=FLOAT," + " encoding=RLE, compression=SNAPPY tags('tag1'='v1', 'tag2'='v2') " + "attributes('attr1'='v1', 'attr2'='v2')";
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute(sql);
        ResultSet resultSet = statement.executeQuery("show timeseries");
        int count = 0;
        try {
            while (resultSet.next()) {
                String ans = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.ALIAS) + "," + resultSet.getString(ColumnHeaderConstant.DATABASE) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.COMPRESSION) + "," + resultSet.getString(ColumnHeaderConstant.TAGS) + "," + resultSet.getString(ColumnHeaderConstant.ATTRIBUTES);
                assertEquals(ret1[count], ans);
                count++;
            }
        } finally {
            resultSet.close();
        }
        assertEquals(ret1.length, count);
        try {
            statement.execute("ALTER timeseries root.turbine.d1.s1 RENAME tag3 TO 'tagNew3'");
            fail();
        } catch (Exception e) {
            assertTrue(e.getMessage().contains("TimeSeries [root.turbine.d1.s1] does not have tag/attribute [tag3]."));
        }
        try {
            statement.execute("ALTER timeseries root.turbine.d1.s1 RENAME 'tag1' TO 'tag2'");
            fail();
        } catch (Exception e) {
            assertTrue(e.getMessage().contains("TimeSeries [root.turbine.d1.s1] already has a tag/attribute named [tag2]."));
        }
        statement.execute("ALTER timeseries root.turbine.d1.s1 RENAME 'tag1' TO 'tagNew1'");
        resultSet = statement.executeQuery("show timeseries");
        count = 0;
        try {
            while (resultSet.next()) {
                String ans = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.ALIAS) + "," + resultSet.getString(ColumnHeaderConstant.DATABASE) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.COMPRESSION) + "," + resultSet.getString(ColumnHeaderConstant.TAGS) + "," + resultSet.getString(ColumnHeaderConstant.ATTRIBUTES);
                assertEquals(ret2[count], ans);
                count++;
            }
        } finally {
            resultSet.close();
        }
        assertEquals(ret2.length, count);
    } catch (Exception e) {
        e.printStackTrace();
        fail();
    }
}

