@Test
public void testOperatePipe() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        try {
            // check exception1: PIPESINK not exist
            statement.execute("CREATE PIPE p to demo;");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("PIPESINK [demo] does not exist"));
        }
        statement.execute(String.format("CREATE PIPESINK demo AS IoTDB (ip='%s',port='%d');", ip, port));
        statement.execute("CREATE PIPE p1 to demo FROM (select ** from root where time>=1648569600000) WITH SyncDelOp=false;");
        statement.execute("CREATE PIPE p2 to demo WITH SyncDelOp=true;");
        try {
            // check exception2: PIPE already exist
            statement.execute("CREATE PIPE p2 to demo;");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("PIPE [p2] is STOP, please retry after drop it"));
        }
        // check pipe operation
        String createTime1 = getCreateTime(statement, "p1");
        String createTime2 = getCreateTime(statement, "p2");
        try (ResultSet resultSet = statement.executeQuery("SHOW PIPE")) {
            String[] expectedRetSet = new String[] { String.format("%s,p1,sender,demo,STOP,SyncDelOp=false,DataStartTimestamp=1648569600000,NORMAL,", createTime1), String.format("%s,p2,sender,demo,STOP,SyncDelOp=true,DataStartTimestamp=0,NORMAL,", createTime2) };
            assertResultSetEqual(resultSet, SHOW_PIPE_HEADER, expectedRetSet);
        }
        statement.execute("START PIPE p1;");
        Awaitility.await().atMost(5, SECONDS).until(() -> {
            try (ResultSet resultSet = statement.executeQuery("SHOW PIPE")) {
                int cnt = 0;
                while (resultSet.next()) {
                    cnt++;
                }
                return cnt == 2;
            }
        });
        try (ResultSet resultSet = statement.executeQuery("SHOW PIPE")) {
            String[] expectedRetSet = new String[] { // there is no data now, so no connection in receiver
            String.format("%s,p1,sender,demo,RUNNING,SyncDelOp=false,DataStartTimestamp=1648569600000,NORMAL,", createTime1), String.format("%s,p2,sender,demo,STOP,SyncDelOp=true,DataStartTimestamp=0,NORMAL,", createTime2) };
            assertResultSetEqual(resultSet, SHOW_PIPE_HEADER, expectedRetSet);
        }
        try {
            statement.execute("START PIPE p3;");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("PIPE [p3] does not exist"));
        }
        try (ResultSet resultSet = statement.executeQuery("SHOW PIPE p1")) {
            String[] expectedRetSet = new String[] { String.format("%s,p1,sender,demo,RUNNING,SyncDelOp=false,DataStartTimestamp=1648569600000,NORMAL,", createTime1) };
            assertResultSetEqual(resultSet, SHOW_PIPE_HEADER, expectedRetSet);
        }
        statement.execute("STOP PIPE p1;");
        statement.execute("STOP PIPE p2;");
        try (ResultSet resultSet = statement.executeQuery("SHOW PIPE")) {
            String[] expectedRetSet = new String[] { String.format("%s,p1,sender,demo,STOP,SyncDelOp=false,DataStartTimestamp=1648569600000,NORMAL,", createTime1), String.format("%s,p2,sender,demo,STOP,SyncDelOp=true,DataStartTimestamp=0,NORMAL,", createTime2) };
            assertResultSetEqual(resultSet, SHOW_PIPE_HEADER, expectedRetSet);
        }
        try {
            statement.execute("STOP PIPE p3;");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("PIPE [p3] does not exist"));
        }
        statement.execute("DROP PIPE p1;");
        statement.execute("DROP PIPE p2;");
        try {
            statement.execute("DROP PIPE p3;");
            Assert.fail();
        } catch (Exception e) {
            Assert.assertTrue(e.getMessage().contains("PIPE [p3] does not exist"));
        }
        try (ResultSet resultSet = statement.executeQuery("SHOW PIPE")) {
            String[] expectedRetSet = new String[] {};
            assertResultSetEqual(resultSet, SHOW_PIPE_HEADER, expectedRetSet);
        }
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail();
    }
}

