        Statement statement = connection.createStatement()) {
        // create first
        statement.execute(String.format("create stateless trigger %s before insert on root.test.stateless.* as '%s' using URI '%s' with (\"name\"=\"%s\")", STATELESS_TRIGGER_BEFORE_INSERTION_PREFIX + "all", TRIGGER_FILE_TIMES_COUNTER, TRIGGER_JAR_PREFIX + "TriggerFireTimesCounter.jar", STATELESS_TRIGGER_BEFORE_INSERTION_PREFIX + "all"));
        statement.execute(String.format("create stateless trigger %s after insert on root.test.stateless.* as '%s' using URI '%s' with (\"name\"=\"%s\")", STATELESS_TRIGGER_AFTER_INSERTION_PREFIX + "all", TRIGGER_FILE_TIMES_COUNTER, TRIGGER_JAR_PREFIX + "TriggerFireTimesCounter.jar", STATELESS_TRIGGER_AFTER_INSERTION_PREFIX + "all"));
        statement.execute(String.format("create stateful trigger %s before insert on root.test.stateful.* as '%s' using URI '%s' with (\"name\"=\"%s\")", STATEFUL_TRIGGER_BEFORE_INSERTION_PREFIX + "all", TRIGGER_FILE_TIMES_COUNTER, TRIGGER_JAR_PREFIX + "TriggerFireTimesCounter.jar", STATEFUL_TRIGGER_BEFORE_INSERTION_PREFIX + "all"));
        statement.execute(String.format("create stateful trigger %s after insert on root.test.stateful.* as '%s' using URI '%s' with (\"name\"=\"%s\")", STATEFUL_TRIGGER_AFTER_INSERTION_PREFIX + "all", TRIGGER_FILE_TIMES_COUNTER, TRIGGER_JAR_PREFIX + "TriggerFireTimesCounter.jar", STATEFUL_TRIGGER_AFTER_INSERTION_PREFIX + "all"));
        // drop triggers
        statement.execute(String.format("drop trigger %s", STATELESS_TRIGGER_BEFORE_INSERTION_PREFIX + "all"));
        statement.execute(String.format("drop trigger %s", STATELESS_TRIGGER_AFTER_INSERTION_PREFIX + "all"));
        statement.execute(String.format("drop trigger %s", STATEFUL_TRIGGER_BEFORE_INSERTION_PREFIX + "all"));
        statement.execute(String.format("drop trigger %s", STATEFUL_TRIGGER_AFTER_INSERTION_PREFIX + "all"));
        ResultSet resultSet = statement.executeQuery("show triggers");
        assertFalse(resultSet.next());
    } catch (Exception e) {
        fail(e.getMessage());
    }
}

