                    ++count;
                }
            }
            Assert.assertEquals(1 + BUILTIN_FUNCTIONS_COUNT, count);
            statement.execute("drop function udf");
        }
    } catch (SQLException throwable) {
        fail(throwable.getMessage());
    }
