@Test
@Category({ LocalStandaloneIT.class, ClusterIT.class })
public void insertIllegalPathTest() {
    try (ISession session = EnvFactory.getEnv().getSessionConnection()) {
        String msg = "[%s] Exception occurred: %s failed. %s is not a legal path";
        String deviceId = "root.sg..d1";
        List<String> deviceIds = Arrays.asList("root.sg..d1", "root.sg.d2");
        List<Long> timestamps = Arrays.asList(1L, 1L);
        List<String> measurements = Arrays.asList("s1", "s2", "s3");
        List<List<String>> allMeasurements = Arrays.asList(measurements, measurements);
        List<TSDataType> tsDataTypes = Arrays.asList(TSDataType.INT32, TSDataType.FLOAT, TSDataType.TEXT);
        List<List<TSDataType>> allTsDataTypes = Arrays.asList(tsDataTypes, tsDataTypes);
        List<TSEncoding> tsEncodings = Arrays.asList(TSEncoding.PLAIN, TSEncoding.PLAIN, TSEncoding.PLAIN);
        List<CompressionType> compressionTypes = Arrays.asList(CompressionType.SNAPPY, CompressionType.SNAPPY, CompressionType.SNAPPY);
        List<Object> values = Arrays.asList(1, 2f, "3");
        List<List<Object>> allValues = Arrays.asList(values, values);
        List<String> stringValues = Arrays.asList("1", "2", "3");
        List<List<String>> allstringValues = Arrays.asList(stringValues, stringValues);
        try {
            session.insertRecords(deviceIds, timestamps, allMeasurements, allTsDataTypes, allValues);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_RECORDS, deviceId)));
        }
        try {
            session.insertRecords(deviceIds, Arrays.asList(2L, 2L), allMeasurements, allstringValues);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_STRING_RECORDS, deviceIds.get(0))));
        }
        try {
            session.insertRecord(deviceId, 3L, measurements, tsDataTypes, values);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_RECORD, deviceId)));
        }
        try {
            session.insertRecord(deviceId, 4L, measurements, stringValues);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_STRING_RECORD, deviceId)));
        }
        try {
            session.insertRecordsOfOneDevice(deviceId, Arrays.asList(5L, 6L), allMeasurements, allTsDataTypes, allValues);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_RECORDS_OF_ONE_DEVICE, deviceId)));
        }
        try {
            session.deleteData(deviceId + ".s1", 6L);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.DELETE_DATA, deviceId + ".s1")));
        }
        try {
            Tablet tablet = new Tablet(deviceId, Arrays.asList(new MeasurementSchema("s1", TSDataType.INT32), new MeasurementSchema("s2", TSDataType.FLOAT)), 5);
            long ts = 7L;
            for (long row = 0; row < 8; row++) {
                int rowIndex = tablet.rowSize++;
                tablet.addTimestamp(rowIndex, ts);
                tablet.addValue("s1", rowIndex, 1);
                tablet.addValue("s2", rowIndex, 1.0F);
                if (tablet.rowSize == tablet.getMaxRowNumber()) {
                    session.insertTablet(tablet, true);
                    tablet.reset();
                }
                ts++;
            }
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_TABLET, deviceId)));
        }
        try {
            Tablet tablet1 = new Tablet(deviceId, Arrays.asList(new MeasurementSchema("s1", TSDataType.INT32), new MeasurementSchema("s2", TSDataType.FLOAT)), 5);
            Tablet tablet2 = new Tablet("root.sg.d2", Arrays.asList(new MeasurementSchema("s1", TSDataType.INT32), new MeasurementSchema("s2", TSDataType.FLOAT)), 5);
            HashMap<String, Tablet> tablets = new HashMap<>();
            tablets.put(deviceId, tablet1);
            tablets.put("root.sg.d2", tablet2);
            long ts = 16L;
            for (long row = 0; row < 8; row++) {
                int row1 = tablet1.rowSize++;
                int row2 = tablet2.rowSize++;
                tablet1.addTimestamp(row1, ts);
                tablet2.addTimestamp(row2, ts);
                tablet1.addValue("s1", row1, 1);
                tablet1.addValue("s2", row1, 1.0F);
                tablet2.addValue("s1", row2, 1);
                tablet2.addValue("s2", row2, 1.0F);
                if (tablet1.rowSize == tablet1.getMaxRowNumber()) {
                    session.insertTablets(tablets, true);
                    tablet1.reset();
                    tablet2.reset();
                }
                ts++;
            }
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.INSERT_TABLETS, deviceId)));
        }
        try {
            session.setStorageGroup("root..sg");
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.SET_STORAGE_GROUP, "root..sg")));
        }
        try {
            session.createTimeseries("root.sg..d1.s1", TSDataType.INT32, TSEncoding.PLAIN, CompressionType.SNAPPY);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.CREATE_TIMESERIES, "root.sg..d1.s1")));
        }
        try {
            session.createAlignedTimeseries(deviceId, measurements, tsDataTypes, tsEncodings, compressionTypes, Arrays.asList("alias1", "alias2", "alias3"), null, null);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.CREATE_ALIGNED_TIMESERIES, deviceId)));
        }
        try {
            session.createMultiTimeseries(Arrays.asList("root.sg.d1..s1", "root.sg.d1.s2", "root.sg.d1.s3"), tsDataTypes, tsEncodings, compressionTypes, null, null, null, null);
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.CREATE_MULTI_TIMESERIES, "root.sg.d1..s1")));
        }
        try {
            session.deleteTimeseries("root.sg.d1..s1");
            fail("Exception expected");
        } catch (StatementExecutionException e) {
            assertTrue(e.getMessage().contains(String.format(msg, TSStatusCode.ILLEGAL_PATH, OperationType.DELETE_TIMESERIES, "root.sg.d1..s1")));
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
@Category({ LocalStandaloneIT.class, ClusterIT.class })
public void conversionFunctionTest() {
    try (ISession session = EnvFactory.getEnv().getSessionConnection()) {
        // prepare data
        String deviceId = "root.sg.d1";
        List<Long> times = new ArrayList<>();
        List<List<String>> measurementsList = new ArrayList<>();
        List<List<TSDataType>> typesList = new ArrayList<>();
        List<List<Object>> valuesList = new ArrayList<>();
        for (int i = 0; i <= 4; i++) {
            times.add((long) i * 2);
            measurementsList.add(Arrays.asList("s1", "s2", "s3", "s4", "s5", "s6"));
            typesList.add(Arrays.asList(TSDataType.INT32, TSDataType.INT64, TSDataType.FLOAT, TSDataType.DOUBLE, TSDataType.BOOLEAN, TSDataType.TEXT));
            valuesList.add(Arrays.asList(i, (long) i + 1, (float) i, (double) i * 2, new boolean[] { true, false }[i % 2], String.valueOf(i)));
        }
        // insert data
        session.insertRecordsOfOneDevice(deviceId, times, measurementsList, typesList, valuesList);
        // excepted
        String[] targetTypes = { "INT64", "INT32", "DOUBLE", "FLOAT", "TEXT", "BOOLEAN" };
        String[] excepted = { "0\t0\t1\t0.0\t0.0\ttrue\ttrue", "2\t1\t2\t1.0\t2.0\tfalse\ttrue", "4\t2\t3\t2.0\t4.0\ttrue\ttrue", "6\t3\t4\t3.0\t6.0\tfalse\ttrue", "8\t4\t5\t4.0\t8.0\ttrue\ttrue" };
        // query
        String[] casts = new String[targetTypes.length];
        StringBuffer buffer = new StringBuffer();
        buffer.append("select ");
        for (int i = 0; i < targetTypes.length; i++) {
            casts[i] = String.format("cast(s%s, 'type'='%s')", i + 1, targetTypes[i]);
        }
        buffer.append(StringUtils.join(casts, ","));
        buffer.append(" from root.sg.d1");
        String sql = buffer.toString();
        SessionDataSet sessionDataSet = session.executeQueryStatement(sql);
        // compare types
        List<String> columnTypes = sessionDataSet.getColumnTypes();
        columnTypes.remove(0);
        for (int i = 0; i < columnTypes.size(); i++) {
            assertEquals(targetTypes[i], columnTypes.get(i));
        }
        // compare results
        int index = 0;
        while (sessionDataSet.hasNext()) {
            RowRecord next = sessionDataSet.next();
            assertEquals(excepted[index], next.toString());
            index++;
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
@Category({ LocalStandaloneIT.class, ClusterIT.class })
public void insertPartialTablet2Test() {
    try (ISession session = EnvFactory.getEnv().getSessionConnection()) {
        if (!session.checkTimeseriesExists("root.sg.d.s1")) {
            session.createTimeseries("root.sg.d.s1", TSDataType.INT64, TSEncoding.RLE, CompressionType.SNAPPY);
        }
        if (!session.checkTimeseriesExists("root.sg.d.s2")) {
            session.createTimeseries("root.sg.d.s2", TSDataType.DOUBLE, TSEncoding.GORILLA, CompressionType.SNAPPY);
        }
        if (!session.checkTimeseriesExists("root.sg.d.s3")) {
            session.createTimeseries("root.sg.d.s3", TSDataType.INT64, TSEncoding.RLE, CompressionType.SNAPPY);
        }
        List<MeasurementSchema> schemaList = new ArrayList<>();
        schemaList.add(new MeasurementSchema("s1", TSDataType.INT64));
        schemaList.add(new MeasurementSchema("s2", TSDataType.DOUBLE));
        schemaList.add(new MeasurementSchema("s3", TSDataType.TEXT));
        Tablet tablet = new Tablet("root.sg.d", schemaList, 10);
        long timestamp = System.currentTimeMillis();
        for (long row = 0; row < 15; row++) {
            int rowIndex = tablet.rowSize++;
            tablet.addTimestamp(rowIndex, timestamp);
            tablet.addValue("s1", rowIndex, 1L);
            tablet.addValue("s2", rowIndex, 1D);
            tablet.addValue("s3", rowIndex, new Binary("1"));
            if (tablet.rowSize == tablet.getMaxRowNumber()) {
                try {
                    session.insertTablet(tablet, true);
                } catch (StatementExecutionException e) {
                    assertTrue(e.getMessage().contains("insert measurements [s3] caused by"));
                    assertTrue(e.getMessage().contains("data type of root.sg.d.s3 is not consistent"));
                }
                tablet.reset();
            }
            timestamp++;
        }
        if (tablet.rowSize != 0) {
            try {
                session.insertTablet(tablet);
            } catch (StatementExecutionException e) {
                assertTrue(e.getMessage().contains("insert measurements [s3] caused by"));
                assertTrue(e.getMessage().contains("data type of root.sg.d.s3 is not consistent"));
            }
            tablet.reset();
        }
        SessionDataSet dataSet = session.executeQueryStatement("select count(s1), count(s2), count(s3) from root.sg.d");
        while (dataSet.hasNext()) {
            RowRecord rowRecord = dataSet.next();
            assertEquals(15L, rowRecord.getFields().get(0).getLongV());
            assertEquals(15L, rowRecord.getFields().get(1).getLongV());
            assertEquals(0L, rowRecord.getFields().get(2).getLongV());
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
@Category({ LocalStandaloneIT.class, ClusterIT.class })
public void insertBinaryAsTextTest() {
    try (ISession session = EnvFactory.getEnv().getSessionConnection()) {
        // prepare binary data
        List<Object> bytesData = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            byte[] bytes = new byte[128];
            for (int j = 0; j < 128; j++) {
                bytes[j] = Byte.valueOf("" + (j - i), 10);
            }
            bytesData.add(bytes);
        }
        // insert data using insertRecord
        for (int i = 0; i < bytesData.size(); i++) {
            byte[] data = (byte[]) bytesData.get(i);
            Binary dataBinary = new Binary(data);
            session.insertRecord("root.sg1.d1", i, Collections.singletonList("s0"), Collections.singletonList(TSDataType.TEXT), dataBinary);
        }
        // insert data using insertTablet
        List<MeasurementSchema> schemaList = new ArrayList<>();
        schemaList.add(new MeasurementSchema("s1", TSDataType.TEXT));
        Tablet tablet = new Tablet("root.sg1.d1", schemaList, 100);
        for (int i = 0; i < bytesData.size(); i++) {
            byte[] data = (byte[]) bytesData.get(i);
            int rowIndex = tablet.rowSize++;
            tablet.addTimestamp(rowIndex, i);
            Binary dataBinary = new Binary(data);
            tablet.addValue(schemaList.get(0).getMeasurementId(), rowIndex, dataBinary);
        }
        session.insertTablet(tablet);
        // check result
        SessionDataSet dataSet = session.executeQueryStatement("select ** from root.sg1.d1");
        assertArrayEquals(dataSet.getColumnNames().toArray(new String[0]), new String[] { "Time", "root.sg1.d1.s0", "root.sg1.d1.s1" });
        while (dataSet.hasNext()) {
            RowRecord rowRecord = dataSet.next();
            for (int i = 0; i < 2; i++) {
                // get Binary value from SessionDataSet
                byte[] actualBytes = rowRecord.getFields().get(i).getBinaryV().getValues();
                // compare Binary value to origin bytesData
                byte[] expectedBytes = (byte[]) bytesData.get((int) rowRecord.getTimestamp());
                assertArrayEquals(expectedBytes, actualBytes);
            }
        }
        dataSet.closeOperationHandle();
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

