        TsFileResource seqResource = seqResources.get(i);
        TsFileResource resource = new TsFileResource(TsFileNameGenerator.increaseCrossCompactionCnt(seqResource.getTsFile()));
        if (i < 2) {
            Assert.assertFalse(resource.getCompactionModFile().exists());
            Assert.assertFalse(resource.getModFile().exists());
        } else {
            Assert.assertFalse(resource.getCompactionModFile().exists());
            Assert.assertTrue(resource.getModFile().exists());
            Assert.assertEquals(1, resource.getModFile().getModifications().size());
        }
    }
}

