public void testOneDeletionDuringCompaction() throws Exception {
    DataRegion vsgp = new DataRegion(STORAGE_GROUP_DIR.getPath(), "0", new TsFileFlushPolicy.DirectFlushPolicy(), COMPACTION_TEST_SG);
    registerTimeseriesInMManger(4, 5, true);
