    createFiles(2, 1, 5, 100, 450, 20450, 0, 0, true, false);
    vsgp.getTsFileResourceManager().addAll(seqResources, true);
    vsgp.getTsFileResourceManager().addAll(unseqResources, false);
    vsgp.deleteByDevice(new PartialPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + (TsFileGeneratorUtils.getAlignDeviceOffset() + 3) + PATH_SEPARATOR + "s0"), 0, 1000, 0, null);
    CrossSpaceCompactionTask task = new CrossSpaceCompactionTask(0, vsgp.getTsFileResourceManager(), seqResources, unseqResources, new ReadPointCompactionPerformer(), new AtomicInteger(0), 0, 0);
    task.setSourceFilesToCompactionCandidate();
    task.checkValidAndSetMerging();
    // delete data in source file during compaction
    vsgp.deleteByDevice(new PartialPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + (TsFileGeneratorUtils.getAlignDeviceOffset() + 3) + PATH_SEPARATOR + "s0"), 0, 1200, 0, null);
