                                            putOnePageChunk(chunkPagePointsNumMerged, fullPaths[7], 600L);
                                            putOnePageChunk(chunkPagePointsNumMerged, fullPaths[8], 600L);
                                            break;
                                        case PAGE_OVERLAP:
                                            putOnePageChunk(chunkPagePointsNumMerged, fullPaths[0], 600L);
