        TSDataType tsDataType = i < 2 ? TSDataType.TEXT : TSDataType.INT64;
        for (int j = 0; j < 7; j++) {
            measurementMaxTime.putIfAbsent(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i + PATH_SEPARATOR + "s" + j, Long.MIN_VALUE);
