@Test
public void testCompatibleWithAllSourceFilesExistWithFileInfo() throws Exception {
    createFiles(6, 2, 3, 100, 0, 0, 50, 50, false, true);
    createFiles(3, 2, 3, 50, 0, 0, 50, 50, false, false);
    registerTimeseriesInMManger(2, 3, false);
    List<TsFileResource> tmpTargetResources = new ArrayList<>();
    for (TsFileResource resource : seqResources) {
        File mergeFile = new File(resource.getTsFilePath() + IoTDBConstant.CROSS_COMPACTION_TMP_FILE_SUFFIX_FROM_OLD);
        mergeFile.createNewFile();
        tmpTargetResources.add(new TsFileResource(mergeFile));
    }
    File logFile = new File(SEQ_DIRS.getPath(), CompactionLogger.CROSS_COMPACTION_LOG_NAME_FROM_OLD);
    BufferedWriter logWriter = new BufferedWriter(new FileWriter(logFile));
    logWriter.write("seqFiles\n");
    for (TsFileResource tsFileResource : seqResources) {
        logWriter.write(String.format(COMPACTION_TEST_SG + " 0 0 %s true\n", tsFileResource.getTsFile().getName()));
    }
    logWriter.write("unseqFiles\n");
    for (TsFileResource tsFileResource : unseqResources) {
        logWriter.write(String.format(COMPACTION_TEST_SG + " 0 0 %s false\n", tsFileResource.getTsFile().getName()));
    }
    logWriter.close();
    for (int i = 0; i < seqResources.size(); i++) {
        Map<String, Pair<Long, Long>> deleteMap = new HashMap<>();
        deleteMap.put(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0" + PATH_SEPARATOR + "s0", new Pair(i * 10L, i * 10L + 10));
        CompactionFileGeneratorUtils.generateMods(deleteMap, seqResources.get(i), false);
    }
    for (int i = 0; i < unseqResources.size(); i++) {
        Map<String, Pair<Long, Long>> deleteMap = new HashMap<>();
        deleteMap.put(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1" + PATH_SEPARATOR + "s1", new Pair(i * 10L, i * 10L + 10));
        CompactionFileGeneratorUtils.generateMods(deleteMap, unseqResources.get(i), false);
    }
    ModificationFile mergeMods = new ModificationFile(SEQ_DIRS + File.separator + IoTDBConstant.COMPACTION_MODIFICATION_FILE_NAME_FROM_OLD);
    mergeMods.write(new Deletion(new PartialPath("root.d1.s1"), 100, 0, 100));
    mergeMods.close();
    TsFileManager tsFileManager = new TsFileManager(COMPACTION_TEST_SG, "0", SEQ_DIRS.getPath());
    new CompactionRecoverTask(COMPACTION_TEST_SG, "0", tsFileManager, logFile, false).doCompaction();
    for (TsFileResource resource : seqResources) {
        Assert.assertTrue(resource.getTsFile().exists());
        Assert.assertTrue(resource.resourceFileExists());
        Assert.assertTrue(resource.getModFile().exists());
    }
    for (TsFileResource resource : unseqResources) {
        Assert.assertTrue(resource.getTsFile().exists());
        Assert.assertTrue(resource.resourceFileExists());
        Assert.assertTrue(resource.getModFile().exists());
    }
    for (TsFileResource resource : tmpTargetResources) {
        Assert.assertFalse(resource.getTsFile().exists());
        Assert.assertFalse(resource.resourceFileExists());
    }
    for (TsFileResource resource : CompactionFileGeneratorUtils.getCrossCompactionTargetTsFileResources(seqResources)) {
        Assert.assertFalse(resource.getTsFile().exists());
        Assert.assertFalse(resource.resourceFileExists());
    }
    Assert.assertFalse(logFile.exists());
    Assert.assertFalse(mergeMods.exists());
}

