@Test
public void testGetInfoFromFileFromSingleDir() throws IOException {
    String firstPath = "sequence" + File.separator + "root.test.sg" + File.separator + "0" + File.separator + "0" + File.separator + "100-10-5-1.tsfile";
    String[] dataDirs = IoTDBDescriptor.getInstance().getConfig().getDataDirs();
    File file = new File(dataDirs[0], firstPath);
    if (file.exists()) {
        Assert.assertTrue(file.delete());
    }
    try {
        TsFileIdentifier info = TsFileIdentifier.getFileIdentifierFromFilePath(firstPath);
        Assert.assertNull(info.getFileFromDataDirs());
        if (!file.getParentFile().exists()) {
            Assert.assertTrue(file.getParentFile().mkdirs());
        }
        Assert.assertTrue(file.createNewFile());
        Assert.assertTrue(Files.isSameFile(file.toPath(), info.getFileFromDataDirs().toPath()));
    } finally {
        file.delete();
    }
}

@Test
public void testGetInfoFromFileFromMultiDirs() throws Exception {
    IoTDBConfig config = IoTDBDescriptor.getInstance().getConfig();
    String[] originDataDirs = config.getDataDirs();
    Class configClass = config.getClass();
    Field dataDirField = configClass.getDeclaredField("dataDirs");
    dataDirField.setAccessible(true);
    dataDirField.set(config, new String[] { "target" + File.separator + "data1", "target" + File.separator + "data2" });
    String filePath = "sequence" + File.separator + "root.test.sg" + File.separator + "0" + File.separator + "0" + File.separator + "100-10-5-1.tsfile";
    File testFile = new File("target" + File.separator + "data2", filePath);
    try {
        TsFileIdentifier info = TsFileIdentifier.getFileIdentifierFromFilePath(filePath);
        if (!testFile.getParentFile().exists()) {
            Assert.assertTrue(testFile.getParentFile().mkdirs());
        }
        if (testFile.exists()) {
            Assert.assertTrue(testFile.delete());
        }
        Assert.assertNull(info.getFileFromDataDirs());
        Assert.assertTrue(testFile.createNewFile());
        Assert.assertTrue(Files.isSameFile(testFile.toPath(), info.getFileFromDataDirs().toPath()));
    } finally {
        dataDirField.set(config, originDataDirs);
        Files.deleteIfExists(testFile.toPath());
        FileUtils.deleteDirectory(new File("target" + File.separator + "data2"));
    }
}

@Test
public void getNonAlignedDevicesFromDifferentFilesWithFourLayersInNodeTreeTest() throws MetadataException, IOException, WriteProcessException {
    TSFileDescriptor.getInstance().getConfig().setMaxDegreeOfIndexNode(3);
    registerTimeseriesInMManger(30, 3, false);
    createFiles(3, 10, 3, 100, 0, 0, 50, 50, false, true);
    createFiles(4, 5, 3, 100, 1000, 0, 50, 50, false, true);
    createFiles(2, 15, 3, 100, 1000, 0, 50, 50, false, false);
    createFiles(3, 30, 3, 100, 1000, 0, 50, 50, false, false);
    // sort the deviceId in lexicographical order from small to large
    List<String> deviceIds = new ArrayList<>();
    for (int i = 0; i < 30; i++) {
        deviceIds.add("root.testsg.d" + i);
    }
    deviceIds.sort(String::compareTo);
    int deviceNum = 0;
    try (MultiTsFileDeviceIterator multiTsFileDeviceIterator = new MultiTsFileDeviceIterator(seqResources, unseqResources)) {
        while (multiTsFileDeviceIterator.hasNextDevice()) {
            Pair<String, Boolean> deviceInfo = multiTsFileDeviceIterator.nextDevice();
            Assert.assertEquals(deviceIds.get(deviceNum), deviceInfo.left);
            Assert.assertFalse(deviceInfo.right);
            deviceNum++;
        }
    }
    Assert.assertEquals(30, deviceNum);
}

