@Test
public void readAndTruncate() {
    String tempFileName = TestConstant.BASE_OUTPUT_PATH.concat("mod.temp");
    File file = new File(tempFileName);
    if (file.exists()) {
        file.delete();
    }
    Modification[] modifications = new Modification[] { new Deletion(new PartialPath(new String[] { "d1", "s1" }), 1, 1), new Deletion(new PartialPath(new String[] { "d1", "s2" }), 2, 2), new Deletion(new PartialPath(new String[] { "d1", "s3" }), 3, 3), new Deletion(new PartialPath(new String[] { "d1", "s4" }), 4, 4) };
    try (LocalTextModificationAccessor accessor = new LocalTextModificationAccessor(tempFileName);
        BufferedWriter writer = new BufferedWriter(new FileWriter(tempFileName, true))) {
        // write normal message
        for (int i = 0; i < 2; i++) {
            accessor.write(modifications[i]);
        }
        List<Modification> modificationList = (List<Modification>) accessor.read();
        for (int i = 0; i < 2; i++) {
            assertEquals(modifications[i], modificationList.get(i));
        }
        // write error message
        long length = file.length();
        writer.write("error");
        writer.newLine();
        writer.flush();
        // write normal message & read
        for (int i = 2; i < 4; i++) {
            accessor.write(modifications[i]);
        }
        modificationList = (List<Modification>) accessor.read();
        for (int i = 0; i < 2; i++) {
            System.out.println(modificationList);
            assertEquals(modifications[i], modificationList.get(i));
        }
        // check truncated file
        assertEquals(length, file.length());
    } catch (IOException e) {
        fail(e.getMessage());
    } finally {
        file.delete();
    }
}

