public void testTTLRead() throws IOException, WriteProcessException, QueryProcessException, MetadataException {
    prepareData();
    // files before ttl
    QueryDataSource dataSource = dataRegion.query(Collections.singletonList(mockMeasurementPath()), sg1, EnvironmentUtils.TEST_QUERY_CONTEXT, null);
