        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    for (File tsfile : file.listFiles()) {
                        if (tsfile.getPath().endsWith(TsFileConstant.TSFILE_SUFFIX)) {
                            unseqFiles.add(file);
                        }
