@Test
public void testSerialization() throws Exception {
    PartialPath[] pathList = new PartialPath[] { new PartialPath("root.sg"), new PartialPath("root.a.sg"), new PartialPath("root.a.b.sg"), new PartialPath("root.a.a.b.sg") };
    for (int i = 0; i < pathList.length; i++) {
        root.setStorageGroup(pathList[i]);
        IStorageGroupMNode storageGroupMNode = root.getStorageGroupNodeByStorageGroupPath(pathList[i]);
        storageGroupMNode.setDataTTL(i);
        storageGroupMNode.setDataReplicationFactor(i);
        storageGroupMNode.setSchemaReplicationFactor(i);
        storageGroupMNode.setTimePartitionInterval(i);
    }
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    root.serialize(outputStream);
    ConfigMTree newTree = new ConfigMTree();
    ByteArrayInputStream inputStream = new ByteArrayInputStream(outputStream.toByteArray());
    newTree.deserialize(inputStream);
    for (int i = 0; i < pathList.length; i++) {
        TStorageGroupSchema storageGroupSchema = newTree.getStorageGroupNodeByStorageGroupPath(pathList[i]).getStorageGroupSchema();
        Assert.assertEquals(i, storageGroupSchema.getTTL());
        Assert.assertEquals(i, storageGroupSchema.getSchemaReplicationFactor());
        Assert.assertEquals(i, storageGroupSchema.getDataReplicationFactor());
        Assert.assertEquals(i, storageGroupSchema.getTimePartitionInterval());
    }
    Assert.assertEquals(3, newTree.getMatchedStorageGroups(new PartialPath("root.**.sg"), false).size());
    Assert.assertEquals(2, newTree.getMatchedStorageGroups(new PartialPath("root.**.b.sg"), false).size());
    Assert.assertEquals(1, newTree.getMatchedStorageGroups(new PartialPath("root.*.*.sg"), false).size());
}

