    MeasurementPath rawPath = new MeasurementPath(new PartialPath("root.sg.d.s"), new MeasurementSchema("s", TSDataType.INT32), true);
    rawPath.setMeasurementAlias("alias");
    String string = MeasurementPath.transformDataToString(rawPath);
    MeasurementPath newPath = MeasurementPath.parseDataFromString(string);
    Assert.assertEquals(rawPath.getFullPath(), newPath.getFullPath());
    Assert.assertEquals(rawPath.getMeasurementAlias(), newPath.getMeasurementAlias());
    Assert.assertEquals(rawPath.getMeasurementSchema(), newPath.getMeasurementSchema());
    Assert.assertEquals(rawPath.isUnderAlignedEntity(), newPath.isUnderAlignedEntity());
}

@Test
public void testMeasurementPathSerde() throws IllegalPathException, IOException {
    IMeasurementSchema schema = new MeasurementSchema("s1", TSDataType.TEXT);
    MeasurementPath expectedPath = new MeasurementPath(new PartialPath("root.sg.d1.s1"), schema, true);
    expectedPath.setMeasurementAlias("alias_s1");
    MeasurementPath actualPath = serdeWithByteBuffer(expectedPath);
    assertMeasurementPathEquals(actualPath, expectedPath);
    actualPath = serdeWithStream(expectedPath);
    assertMeasurementPathEquals(actualPath, expectedPath);
    HashMap<String, String> tagMap = new HashMap<>();
    tagMap.put("k1", "v1");
    expectedPath.setTagMap(tagMap);
    actualPath = serdeWithByteBuffer(expectedPath);
    assertMeasurementPathEquals(actualPath, expectedPath);
    actualPath = serdeWithStream(expectedPath);
    assertMeasurementPathEquals(actualPath, expectedPath);
}

@Test
public void testCloneAndCopy() throws IllegalPathException {
    IMeasurementSchema schema = new MeasurementSchema("s1", TSDataType.TEXT);
    MeasurementPath expectedPath = new MeasurementPath(new PartialPath("root.sg.d1.s1"), schema, true);
    expectedPath.setMeasurementAlias("alias_s1");
    MeasurementPath actualPath = expectedPath.clone();
    assertMeasurementPathEquals(actualPath, expectedPath);
    actualPath = (MeasurementPath) expectedPath.copy();
    assertMeasurementPathEquals(actualPath, expectedPath);
    HashMap<String, String> tagMap = new HashMap<>();
    tagMap.put("k1", "v1");
    expectedPath.setTagMap(tagMap);
    actualPath = expectedPath.clone();
    assertMeasurementPathEquals(actualPath, expectedPath);
    actualPath = (MeasurementPath) expectedPath.copy();
    assertMeasurementPathEquals(actualPath, expectedPath);
}

@Test
public void stringAppendPatternTreeMapTest() throws IllegalPathException {
    PatternTreeMap<String, StringSerializer> patternTreeMap = PatternTreeMapFactory.getTriggerPatternTreeMap();
    patternTreeMap.append(new PartialPath("root.sg1.d1.s1"), "A");
    patternTreeMap.append(new PartialPath("root.**.s1"), "B");
    patternTreeMap.append(new PartialPath("root.sg1.*.s1"), "C");
    patternTreeMap.append(new PartialPath("root.sg1.d1.s1"), "D");
    patternTreeMap.append(new PartialPath("root.sg1.**"), "E");
    patternTreeMap.append(new PartialPath("root.sg1.**.s2"), "F");
    patternTreeMap.append(new PartialPath("root.**.d1.*"), "G");
    patternTreeMap.append(new PartialPath("root.**.d1.**"), "H");
    patternTreeMap.append(new PartialPath("root.*.d1.**"), "I");
    patternTreeMap.append(new PartialPath("root.**"), "J");
    patternTreeMap.append(new PartialPath("root.**.**"), "K");
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s1"), Arrays.asList("A", "B", "C", "D", "E", "G", "H", "I", "J", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg2.s1"), Arrays.asList("B", "J", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s2"), Arrays.asList("E", "F", "G", "H", "I", "J", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.v1.s1"), Arrays.asList("B", "E", "H", "I", "J", "K"));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d1"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("A", "B", "C", "D", "E", "G", "H", "I", "J", "K"), Arrays.asList("E", "F", "G", "H", "I", "J", "K")));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d2"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("B", "C", "E", "J", "K"), Arrays.asList("E", "F", "J", "K")));
    // delete leaf node with common parent
    patternTreeMap.delete(new PartialPath("root.**.d1.*"), "G");
    // only delete value, no delete leaf node
    patternTreeMap.delete(new PartialPath("root.sg1.d1.s1"), "D");
    // delete internal node
    patternTreeMap.delete(new PartialPath("root.**"), "J");
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s1"), Arrays.asList("A", "B", "C", "E", "H", "I", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s2"), Arrays.asList("E", "F", "H", "I", "K"));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.v1.s1"), Arrays.asList("B", "E", "H", "I", "K"));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d1"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("A", "B", "C", "E", "H", "I", "K"), Arrays.asList("E", "F", "H", "I", "K")));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.d2"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("B", "C", "E", "K"), Arrays.asList("E", "F", "K")));
    checkOverlappedByDeviceMeasurements(patternTreeMap, new PartialPath("root.sg1.v1.d1"), Arrays.asList("s1", "s2"), Arrays.asList(Arrays.asList("B", "E", "H", "K"), Arrays.asList("E", "F", "H", "K")));
}

@Test
public void modificationPatternTreeMapTest() throws IllegalPathException {
    PatternTreeMap<Modification, ModsSerializer> patternTreeMap = PatternTreeMapFactory.getModsPatternTreeMap();
    // [1,3] [6,10]
    patternTreeMap.append(new PartialPath("root.sg1.d1.s1"), new Deletion(new PartialPath("root.sg1.d1.s1"), 1, 1, 3));
    patternTreeMap.append(new PartialPath("root.sg1.d1.s1"), new Deletion(new PartialPath("root.sg1.d1.s1"), 1, 6, 10));
    patternTreeMap.append(new PartialPath("root.**.s1"), new Deletion(new PartialPath("root.**.s1"), 5, 10, 100));
    patternTreeMap.append(new PartialPath("root.**.s1"), new Deletion(new PartialPath("root.**.s1"), 10, 100, 200));
    patternTreeMap.append(new PartialPath("root.**"), new Deletion(new PartialPath("root.**"), 5, 10, 100));
    patternTreeMap.append(new PartialPath("root.**"), new Deletion(new PartialPath("root.**"), 5, 10, 100));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s1"), Arrays.asList(new Deletion(new PartialPath("root.sg1.d1.s1"), 1, 1, 3), new Deletion(new PartialPath("root.sg1.d1.s1"), 1, 6, 10), new Deletion(new PartialPath("root.**.s1"), 5, 10, 100), new Deletion(new PartialPath("root.**.s1"), 10, 100, 200), new Deletion(new PartialPath("root.**"), 5, 10, 100)));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d2.s1"), Arrays.asList(new Deletion(new PartialPath("root.**.s1"), 5, 10, 100), new Deletion(new PartialPath("root.**.s1"), 10, 100, 200), new Deletion(new PartialPath("root.**"), 5, 10, 100)));
    checkOverlapped(patternTreeMap, new PartialPath("root.sg1.d1.s2"), Collections.singletonList(new Deletion(new PartialPath("root.**"), 5, 10, 100)));
}

