public void testMultiWildcard() throws IllegalPathException {
    SchemaNode root = generateSchemaTreeWithInternalRepeatedName();
    SchemaTreeVisitorWithLimitOffsetWrapper<MeasurementPath> visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.**.**.s"), 0, 0, false);
