    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.*.**.s"), 0, 0, false);
    checkVisitorResult(visitor, 4, new String[] { "root.a.a.a.a.a.s", "root.a.a.a.a.s", "root.a.a.a.s", "root.a.a.s" }, null, new boolean[] { false, false, false, false });
    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.**.a.**.s"), 0, 0, false);
    checkVisitorResult(visitor, 3, new String[] { "root.a.a.a.a.a.s", "root.a.a.a.a.s", "root.a.a.a.s" }, null, new boolean[] { false, false, false });
    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.**.a.**.*.s"), 0, 0, false);
    checkVisitorResult(visitor, 2, new String[] { "root.a.a.a.a.a.s", "root.a.a.a.a.s" }, null, new boolean[] { false, false, false });
    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.a.**.a.*.s"), 0, 0, false);
    checkVisitorResult(visitor, 2, new String[] { "root.a.a.a.a.a.s", "root.a.a.a.a.s" }, null, new boolean[] { false, false, false });
    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.**.c.s1"), 0, 0, false);
    checkVisitorResult(visitor, 2, new String[] { "root.c.c.c.d.c.c.s1", "root.c.c.c.d.c.s1" }, null, new boolean[] { false, false });
    visitor = createSchemaTreeVisitorWithLimitOffsetWrapper(root, new PartialPath("root.**.c.d.c.s1"), 0, 0, false);
    checkVisitorResult(visitor, 1, new String[] { "root.c.c.c.d.c.s1" }, null, new boolean[] { false });
