    final String queryId = "q0";
    final long mockTsBlockSize = 1024L * 1024L;
    final int numOfMockTsBlock = 1;
    final TEndPoint remoteEndpoint = new TEndPoint("remote", IoTDBDescriptor.getInstance().getConfig().getMppDataExchangePort());
    final TFragmentInstanceId remoteFragmentInstanceId = new TFragmentInstanceId(queryId, 0, "0");
    final String remotePlanNodeId = "exchange_0";
    final String localPlanNodeId = "fragmentSink_0";
    final TFragmentInstanceId localFragmentInstanceId = new TFragmentInstanceId(queryId, 1, "0");
    // Construct a mock LocalMemoryManager that returns blocked futures.
    LocalMemoryManager mockLocalMemoryManager = Mockito.mock(LocalMemoryManager.class);
    MemoryPool spyMemoryPool = Mockito.spy(new MemoryPool("test", numOfMockTsBlock * mockTsBlockSize, numOfMockTsBlock * mockTsBlockSize));
    Mockito.when(mockLocalMemoryManager.getQueryPool()).thenReturn(spyMemoryPool);
    // Construct a mock SinkHandleListener.
    SinkHandleListener mockSinkHandleListener = Mockito.mock(SinkHandleListener.class);
    // Construct several mock TsBlock(s).
    List<TsBlock> mockTsBlocks = Utils.createMockTsBlocks(numOfMockTsBlock, mockTsBlockSize);
    IClientManager<TEndPoint, SyncDataNodeMPPDataExchangeServiceClient> mockClientManager = Mockito.mock(IClientManager.class);
    // Construct a mock client.
    SyncDataNodeMPPDataExchangeServiceClient mockClient = Mockito.mock(SyncDataNodeMPPDataExchangeServiceClient.class);
    try {
        Mockito.when(mockClientManager.borrowClient(remoteEndpoint)).thenReturn(mockClient);
        Mockito.doNothing().when(mockClient).onEndOfDataBlockEvent(Mockito.any(TEndOfDataBlockEvent.class));
        Mockito.doNothing().when(mockClient).onNewDataBlockEvent(Mockito.any(TNewDataBlockEvent.class));
    } catch (ClientManagerException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Construct SinkHandle.
    SinkHandle sinkHandle = new SinkHandle(remoteEndpoint, remoteFragmentInstanceId, remotePlanNodeId, localPlanNodeId, localFragmentInstanceId, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), Utils.createMockTsBlockSerde(mockTsBlockSize), mockSinkHandleListener, mockClientManager);
    sinkHandle.setMaxBytesCanReserve(Long.MAX_VALUE);
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES, sinkHandle.getBufferRetainedSizeInBytes());
    Assert.assertEquals(0, sinkHandle.getNumOfBufferedTsBlocks());
    // Send tsblocks.
    sinkHandle.send(mockTsBlocks.get(0));
    Future<?> blocked = sinkHandle.isFull();
    Assert.assertFalse(blocked.isDone());
    Assert.assertFalse(blocked.isCancelled());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(mockTsBlockSize * numOfMockTsBlock + DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES, sinkHandle.getBufferRetainedSizeInBytes());
    Assert.assertEquals(numOfMockTsBlock, sinkHandle.getNumOfBufferedTsBlocks());
    sinkHandle.abort();
    Assert.assertTrue(blocked.isDone());
    Assert.assertTrue(blocked.isCancelled());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertTrue(sinkHandle.isAborted());
    Assert.assertEquals(0L, sinkHandle.getBufferRetainedSizeInBytes());
    Assert.assertEquals(0, sinkHandle.getNumOfBufferedTsBlocks());
    Mockito.verify(mockSinkHandleListener, Mockito.timeout(10_0000).times(1)).onAborted(sinkHandle);
    Assert.assertEquals(0L, spyMemoryPool.getQueryMemoryReservedBytes(queryId));
}

@Test
public void testNonBlockedOneTimeReceive() {
    final String queryId = "q0";
    final int numOfMockTsBlock = 10;
    final TEndPoint remoteEndpoint = new TEndPoint("remote", IoTDBDescriptor.getInstance().getConfig().getMppDataExchangePort());
    final TFragmentInstanceId remoteFragmentInstanceId = new TFragmentInstanceId(queryId, 1, "0");
    final String localPlanNodeId = "exchange_0";
    final TFragmentInstanceId localFragmentInstanceId = new TFragmentInstanceId(queryId, 0, "0");
    // Construct a mock LocalMemoryManager that do not block any reservation.
    LocalMemoryManager mockLocalMemoryManager = Mockito.mock(LocalMemoryManager.class);
    MemoryPool mockMemoryPool = Utils.createMockNonBlockedMemoryPool();
    Mockito.when(mockLocalMemoryManager.getQueryPool()).thenReturn(mockMemoryPool);
    IClientManager<TEndPoint, SyncDataNodeMPPDataExchangeServiceClient> mockClientManager = Mockito.mock(IClientManager.class);
    // Construct a mock client.
    SyncDataNodeMPPDataExchangeServiceClient mockClient = Mockito.mock(SyncDataNodeMPPDataExchangeServiceClient.class);
    try {
        Mockito.when(mockClientManager.borrowClient(remoteEndpoint)).thenReturn(mockClient);
        Mockito.doAnswer(invocation -> {
            TGetDataBlockRequest req = invocation.getArgument(0);
            List<ByteBuffer> byteBuffers = new ArrayList<>(req.getEndSequenceId() - req.getStartSequenceId());
            for (int i = 0; i < req.getEndSequenceId() - req.getStartSequenceId(); i++) {
                byteBuffers.add(ByteBuffer.allocate(0));
            }
            return new TGetDataBlockResponse(byteBuffers);
        }).when(mockClient).getDataBlock(Mockito.any(TGetDataBlockRequest.class));
    } catch (ClientManagerException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Construct a mock SourceHandleListener.
    SourceHandleListener mockSourceHandleListener = Mockito.mock(SourceHandleListener.class);
    // Construct a mock TsBlockSerde that deserializes any bytebuffer into a mock TsBlock.
    TsBlockSerde mockTsBlockSerde = Utils.createMockTsBlockSerde(MOCK_TSBLOCK_SIZE);
    SourceHandle sourceHandle = new SourceHandle(remoteEndpoint, remoteFragmentInstanceId, localFragmentInstanceId, localPlanNodeId, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), mockTsBlockSerde, mockSourceHandleListener, mockClientManager);
    Assert.assertFalse(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    // New data blocks event arrived.
    sourceHandle.updatePendingDataBlockInfo(0, Stream.generate(() -> MOCK_TSBLOCK_SIZE).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && 0 == req.getStartSequenceId() && numOfMockTsBlock == req.getEndSequenceId()));
        Mockito.verify(mockClient, Mockito.timeout(10_0000).times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && 0 == e.getStartSequenceId() && numOfMockTsBlock == e.getEndSequenceId()));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(numOfMockTsBlock * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    // The local fragment instance consumes the data blocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        sourceHandle.receive();
        if (i < numOfMockTsBlock - 1) {
            Assert.assertTrue(sourceHandle.isBlocked().isDone());
        } else {
            Assert.assertFalse(sourceHandle.isBlocked().isDone());
        }
        Assert.assertFalse(sourceHandle.isAborted());
        Assert.assertFalse(sourceHandle.isFinished());
        Assert.assertEquals((numOfMockTsBlock - 1 - i) * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    }
    // Receive EndOfDataBlock event from upstream fragment instance.
    sourceHandle.setNoMoreTsBlocks(numOfMockTsBlock - 1);
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertTrue(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    Mockito.verify(mockSourceHandleListener, Mockito.timeout(10_0000).times(1)).onFinished(sourceHandle);
}

@Test
public void testBlockedOneTimeReceive() {
    final String queryId = "q0";
    final int numOfMockTsBlock = 10;
    final TEndPoint remoteEndpoint = new TEndPoint("remote", IoTDBDescriptor.getInstance().getConfig().getMppDataExchangePort());
    final TFragmentInstanceId remoteFragmentInstanceId = new TFragmentInstanceId(queryId, 1, "0");
    final String localPlanNodeId = "exchange_0";
    final TFragmentInstanceId localFragmentInstanceId = new TFragmentInstanceId(queryId, 0, "0");
    // Construct a mock LocalMemoryManager with capacity 5 * MOCK_TSBLOCK_SIZE per query.
    LocalMemoryManager mockLocalMemoryManager = Mockito.mock(LocalMemoryManager.class);
    MemoryPool spyMemoryPool = Mockito.spy(new MemoryPool("test", 10 * MOCK_TSBLOCK_SIZE, 5 * MOCK_TSBLOCK_SIZE));
    Mockito.when(mockLocalMemoryManager.getQueryPool()).thenReturn(spyMemoryPool);
    IClientManager<TEndPoint, SyncDataNodeMPPDataExchangeServiceClient> mockClientManager = Mockito.mock(IClientManager.class);
    // Construct a mock client.
    SyncDataNodeMPPDataExchangeServiceClient mockClient = Mockito.mock(SyncDataNodeMPPDataExchangeServiceClient.class);
    try {
        Mockito.when(mockClientManager.borrowClient(remoteEndpoint)).thenReturn(mockClient);
        Mockito.doAnswer(invocation -> {
            TGetDataBlockRequest req = invocation.getArgument(0);
            List<ByteBuffer> byteBuffers = new ArrayList<>(req.getEndSequenceId() - req.getStartSequenceId());
            for (int i = 0; i < req.getEndSequenceId() - req.getStartSequenceId(); i++) {
                byteBuffers.add(ByteBuffer.allocate(0));
            }
            return new TGetDataBlockResponse(byteBuffers);
        }).when(mockClient).getDataBlock(Mockito.any(TGetDataBlockRequest.class));
    } catch (ClientManagerException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Construct a mock SourceHandleListener.
    SourceHandleListener mockSourceHandleListener = Mockito.mock(SourceHandleListener.class);
    // Construct a mock TsBlockSerde that deserializes any bytebuffer into a mock TsBlock.
    TsBlockSerde mockTsBlockSerde = Utils.createMockTsBlockSerde(MOCK_TSBLOCK_SIZE);
    SourceHandle sourceHandle = new SourceHandle(remoteEndpoint, remoteFragmentInstanceId, localFragmentInstanceId, localPlanNodeId, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), mockTsBlockSerde, mockSourceHandleListener, mockClientManager);
    long maxBytesCanReserve = Math.min(5 * MOCK_TSBLOCK_SIZE, IoTDBDescriptor.getInstance().getConfig().getMaxBytesPerFragmentInstance());
    sourceHandle.setMaxBytesCanReserve(maxBytesCanReserve);
    Assert.assertFalse(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    // New data blocks event arrived.
    sourceHandle.updatePendingDataBlockInfo(0, Stream.generate(() -> MOCK_TSBLOCK_SIZE).limit(numOfMockTsBlock).collect(Collectors.toList()));
    try {
        Mockito.verify(spyMemoryPool, Mockito.timeout(10_000).times(6)).reserve(queryId, localFragmentInstanceId.getInstanceId(), localPlanNodeId, MOCK_TSBLOCK_SIZE, maxBytesCanReserve);
        Mockito.verify(mockClient, Mockito.timeout(10_0000).times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && 0 == req.getStartSequenceId() && 5 == req.getEndSequenceId()));
        Mockito.verify(mockClient, Mockito.timeout(10_0000).times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && 0 == e.getStartSequenceId() && 5 == e.getEndSequenceId()));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertFalse(sourceHandle.isFinished());
    Assert.assertEquals(6 * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
    // The local fragment instance consumes the data blocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        Mockito.verify(spyMemoryPool, Mockito.timeout(10_0000).times(i)).free(queryId, localFragmentInstanceId.getInstanceId(), localPlanNodeId, MOCK_TSBLOCK_SIZE);
        sourceHandle.receive();
        try {
            if (i < 5) {
                Assert.assertEquals(i == 4 ? 5 * MOCK_TSBLOCK_SIZE : 6 * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
                final int startSequenceId = 5 + i;
                Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).getDataBlock(Mockito.argThat(req -> remoteFragmentInstanceId.equals(req.getSourceFragmentInstanceId()) && startSequenceId == req.getStartSequenceId() && startSequenceId + 1 == req.getEndSequenceId()));
                Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).onAcknowledgeDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && startSequenceId == e.getStartSequenceId() && startSequenceId + 1 == e.getEndSequenceId()));
            } else {
                Assert.assertEquals((numOfMockTsBlock - 1 - i) * MOCK_TSBLOCK_SIZE, sourceHandle.getBufferRetainedSizeInBytes());
            }
        } catch (TException e) {
            e.printStackTrace();
            Assert.fail();
        }
        if (i < numOfMockTsBlock - 1) {
            Assert.assertTrue(sourceHandle.isBlocked().isDone());
        } else {
            Assert.assertFalse(sourceHandle.isBlocked().isDone());
        }
        Assert.assertFalse(sourceHandle.isAborted());
        Assert.assertFalse(sourceHandle.isFinished());
    }
    // Receive EndOfDataBlock event from upstream fragment instance.
    sourceHandle.setNoMoreTsBlocks(numOfMockTsBlock - 1);
    Assert.assertTrue(sourceHandle.isBlocked().isDone());
    Assert.assertFalse(sourceHandle.isAborted());
    Assert.assertTrue(sourceHandle.isFinished());
    Assert.assertEquals(0L, sourceHandle.getBufferRetainedSizeInBytes());
    Mockito.verify(mockSourceHandleListener, Mockito.timeout(10_0000).times(1)).onFinished(sourceHandle);
}

