        driverContext.addOperatorContext(2, planNodeId2, SeriesScanOperator.class.getSimpleName());
        PlanNodeId planNodeId3 = new PlanNodeId("3");
        driverContext.addOperatorContext(3, planNodeId3, DeviceViewOperatorTest.class.getSimpleName());
        PlanNodeId planNodeId4 = new PlanNodeId("4");
        driverContext.addOperatorContext(4, planNodeId4, DeviceViewOperatorTest.class.getSimpleName());
        PlanNodeId planNodeId5 = new PlanNodeId("5");
        driverContext.addOperatorContext(5, planNodeId5, DeviceMergeOperator.class.getSimpleName());
        List<TSDataType> dataTypes = new ArrayList<>();
        dataTypes.add(TSDataType.TEXT);
        dataTypes.add(TSDataType.INT32);
        dataTypes.add(TSDataType.INT32);
        MeasurementPath measurementPath1 = new MeasurementPath(DEVICE_MERGE_OPERATOR_TEST_SG + ".device0.sensor0", TSDataType.INT32);
        SeriesScanOperator seriesScanOperator1 = new SeriesScanOperator(driverContext.getOperatorContexts().get(0), planNodeId1, measurementPath1, Collections.singleton("sensor0"), TSDataType.INT32, null, null, true);
        seriesScanOperator1.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator1.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        DeviceViewOperator deviceViewOperator1 = new DeviceViewOperator(driverContext.getOperatorContexts().get(2), Collections.singletonList(DEVICE_MERGE_OPERATOR_TEST_SG + ".device0"), Collections.singletonList(seriesScanOperator1), Collections.singletonList(Collections.singletonList(1)), dataTypes);
        MeasurementPath measurementPath2 = new MeasurementPath(DEVICE_MERGE_OPERATOR_TEST_SG + ".device1.sensor1", TSDataType.INT32);
        SeriesScanOperator seriesScanOperator2 = new SeriesScanOperator(driverContext.getOperatorContexts().get(1), planNodeId2, measurementPath2, Collections.singleton("sensor1"), TSDataType.INT32, null, null, true);
        seriesScanOperator2.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator2.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        DeviceViewOperator deviceViewOperator2 = new DeviceViewOperator(driverContext.getOperatorContexts().get(3), Collections.singletonList(DEVICE_MERGE_OPERATOR_TEST_SG + ".device1"), Collections.singletonList(seriesScanOperator2), Collections.singletonList(Collections.singletonList(2)), dataTypes);
