            public long calculateMaxPeekMemory() {
                return 0;
            }

            @Override
            public long calculateMaxReturnSize() {
                return 0;
            }

            @Override
            public long calculateRetainedSizeAfterCallingNext() {
                return 0;
            }
        });
        int count = 0;
        double[][][] res = new double[][][] { { { 1.0, 520.0, 100.0 }, { 2, 20, 200 }, { 3, 30, 520.0 }, { 520.0, 40, 520.0 }, { 520.0, 520.0, 500 } }, { { 10001, 520.0, 10100 }, { 10002, 10020, 10200 }, { 10003, 10030, 520.0 }, { 520.0, 10040, 520.0 }, { 520.0, 520.0, 10500 } }, { { 20001, 520.0, 20100 }, { 20002, 20020, 20200 }, { 20003, 20030, 520.0 }, { 520.0, 20040, 520.0 }, { 520.0, 520.0, 20500 } } };
        boolean[][][] isNull = new boolean[][][] { { { false, false, false }, { false, false, false }, { false, false, false }, { false, false, false }, { false, false, false } }, { { false, false, false }, { false, false, false }, { false, false, false }, { false, false, false }, { false, false, false } }, { { false, false, false }, { false, false, false }, { false, false, false }, { false, false, false }, { false, false, false } } };
        while (fillOperator.hasNext()) {
