                        assertEquals(res[count][i][j], block.getColumn(j).getDouble(i), 0.00001);
                    }
                }
            }
            count++;
        }
        assertTrue(fillOperator.isFinished());
        assertEquals(3, count);
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

