@Test
public void mergeSortWithSortOperatorTest() {
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    try {
        // Construct operator tree
        QueryId queryId = new QueryId("stub_query");
        FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(queryId, 0), "stub-instance");
        FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
        FragmentInstanceContext fragmentInstanceContext = createFragmentInstanceContext(instanceId, stateMachine);
        DriverContext driverContext = new DriverContext(fragmentInstanceContext, 0);
        PlanNodeId planNodeId0 = new PlanNodeId("0");
        driverContext.addOperatorContext(0, planNodeId0, ShowQueriesOperator.class.getSimpleName());
        PlanNodeId planNodeId1 = new PlanNodeId("1");
        driverContext.addOperatorContext(1, planNodeId1, ShowQueriesOperator.class.getSimpleName());
        PlanNodeId planNodeId2 = new PlanNodeId("2");
        driverContext.addOperatorContext(2, planNodeId2, SortOperator.class.getSimpleName());
        PlanNodeId planNodeId3 = new PlanNodeId("3");
        driverContext.addOperatorContext(3, planNodeId3, SortOperator.class.getSimpleName());
        PlanNodeId planNodeId4 = new PlanNodeId("4");
        driverContext.addOperatorContext(4, planNodeId4, MergeSortOperator.class.getSimpleName());
        List<OperatorContext> operatorContexts = driverContext.getOperatorContexts();
        List<TSDataType> dataTypes = DatasetHeaderFactory.getShowQueriesHeader().getRespDataTypes();
        Comparator<MergeSortKey> comparator = MergeSortComparator.getComparator(Arrays.asList(new SortItem(SortKey.TIME, Ordering.ASC), new SortItem(SortKey.DATANODEID, Ordering.DESC)), ImmutableList.of(-1, 1), ImmutableList.of(TSDataType.INT64, TSDataType.INT32));
        Coordinator coordinator1 = Mockito.mock(Coordinator.class);
        Mockito.when(coordinator1.getAllQueryExecutions()).thenReturn(ImmutableList.of(new FakeQueryExecution(3, "20221229_000000_00003_1", "sql3_node1"), new FakeQueryExecution(1, "20221229_000000_00001_1", "sql1_node1"), new FakeQueryExecution(2, "20221229_000000_00002_1", "sql2_node1")));
        Coordinator coordinator2 = Mockito.mock(Coordinator.class);
        Mockito.when(coordinator2.getAllQueryExecutions()).thenReturn(ImmutableList.of(new FakeQueryExecution(3, "20221229_000000_00003_2", "sql3_node2"), new FakeQueryExecution(2, "20221229_000000_00002_2", "sql2_node2"), new FakeQueryExecution(1, "20221229_000000_00001_2", "sql1_node2")));
        ShowQueriesOperator showQueriesOperator1 = new ShowQueriesOperator(operatorContexts.get(0), planNodeId0, coordinator1);
        ShowQueriesOperator showQueriesOperator2 = new ShowQueriesOperator(operatorContexts.get(1), planNodeId1, coordinator2);
        SortOperator sortOperator1 = new SortOperator(operatorContexts.get(2), showQueriesOperator1, dataTypes, comparator);
        SortOperator sortOperator2 = new SortOperator(operatorContexts.get(3), showQueriesOperator2, dataTypes, comparator);
        Operator root = new MergeSortOperator(operatorContexts.get(4), ImmutableList.of(sortOperator1, sortOperator2), dataTypes, comparator);
        int index = 0;
        // Time ASC
        long[] expectedTime = new long[] { 1, 1, 2, 2, 3, 3 };
        // DataNodeId DESC if Times are equal
        String[] expectedQueryId = new String[] { "20221229_000000_00001_2", "20221229_000000_00001_1", "20221229_000000_00002_2", "20221229_000000_00002_1", "20221229_000000_00003_2", "20221229_000000_00003_1" };
        int[] expectedDataNodeId = new int[] { 2, 1, 2, 1, 2, 1 };
        String[] expectedStatement = new String[] { "sql1_node2", "sql1_node1", "sql2_node2", "sql2_node1", "sql3_node2", "sql3_node1" };
        while (root.hasNext()) {
            TsBlock result = root.next();
            if (result == null) {
                continue;
            }
            for (int i = 0; i < result.getPositionCount(); i++, index++) {
                assertEquals(expectedTime[index], result.getTimeColumn().getLong(i));
                assertEquals(expectedQueryId[index], result.getColumn(0).getBinary(i).toString());
                assertEquals(expectedDataNodeId[index], result.getColumn(1).getInt(i));
                assertEquals(expectedStatement[index], result.getColumn(3).getBinary(i).toString());
            }
        }
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

@Test
public void mergeTest1() {
    MultiColumnMerger merger = new MultiColumnMerger(ImmutableList.of(new InputLocation(0, 0), new InputLocation(1, 0)));
    TsBlockBuilder inputBuilder1 = new TsBlockBuilder(Collections.singletonList(TSDataType.INT32));
    inputBuilder1.getTimeColumnBuilder().writeLong(2);
    inputBuilder1.getColumnBuilder(0).writeInt(20);
    inputBuilder1.declarePosition();
    inputBuilder1.getTimeColumnBuilder().writeLong(4);
    inputBuilder1.getColumnBuilder(0).writeInt(40);
    inputBuilder1.declarePosition();
    inputBuilder1.getTimeColumnBuilder().writeLong(5);
    inputBuilder1.getColumnBuilder(0).appendNull();
    inputBuilder1.declarePosition();
    inputBuilder1.getTimeColumnBuilder().writeLong(6);
    inputBuilder1.getColumnBuilder(0).writeInt(60);
    inputBuilder1.declarePosition();
    TsBlockBuilder inputBuilder2 = new TsBlockBuilder(Collections.singletonList(TSDataType.INT32));
    inputBuilder2.getTimeColumnBuilder().writeLong(8);
    inputBuilder2.getColumnBuilder(0).writeInt(800);
    inputBuilder2.declarePosition();
    inputBuilder2.getTimeColumnBuilder().writeLong(10);
    inputBuilder2.getColumnBuilder(0).writeInt(1000);
    inputBuilder2.declarePosition();
    TsBlock[] inputTsBlocks = new TsBlock[] { inputBuilder1.build(), inputBuilder2.build() };
    int[] inputIndex = new int[] { 1, 0 };
    int[] updatedInputIndex = new int[] { 1, 0 };
    TsBlockBuilder builder = new TsBlockBuilder(Collections.singletonList(TSDataType.INT32));
    TimeColumnBuilder timeColumnBuilder = builder.getTimeColumnBuilder();
    timeColumnBuilder.writeLong(4);
    builder.declarePosition();
    timeColumnBuilder.writeLong(5);
    builder.declarePosition();
    timeColumnBuilder.writeLong(6);
    builder.declarePosition();
    timeColumnBuilder.writeLong(7);
    builder.declarePosition();
    timeColumnBuilder.writeLong(8);
    builder.declarePosition();
    timeColumnBuilder.writeLong(9);
    builder.declarePosition();
    timeColumnBuilder.writeLong(10);
    builder.declarePosition();
    timeColumnBuilder.writeLong(11);
    builder.declarePosition();
    ColumnBuilder valueColumnBuilder = builder.getColumnBuilder(0);
    merger.mergeColumn(inputTsBlocks, inputIndex, updatedInputIndex, timeColumnBuilder, 11, valueColumnBuilder);
    assertEquals(4, updatedInputIndex[0]);
    assertEquals(2, updatedInputIndex[1]);
    Column result = valueColumnBuilder.build();
    assertEquals(8, result.getPositionCount());
    assertFalse(result.isNull(0));
    assertEquals(40, result.getInt(0));
    assertTrue(result.isNull(1));
    assertFalse(result.isNull(2));
    assertEquals(60, result.getInt(2));
    assertTrue(result.isNull(3));
    assertFalse(result.isNull(4));
    assertEquals(800, result.getInt(4));
    assertTrue(result.isNull(5));
    assertFalse(result.isNull(6));
    assertEquals(1000, result.getInt(6));
    assertTrue(result.isNull(7));
}

