@Test
public void batchTest() {
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    try {
        MeasurementPath measurementPath = new MeasurementPath(SERIES_SCAN_OPERATOR_TEST_SG + ".device0.sensor0", TSDataType.INT32);
        Set<String> allSensors = Sets.newHashSet("sensor0");
        QueryId queryId = new QueryId("stub_query");
        FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(queryId, 0), "stub-instance");
        FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
        FragmentInstanceContext fragmentInstanceContext = createFragmentInstanceContext(instanceId, stateMachine);
        DriverContext driverContext = new DriverContext(fragmentInstanceContext, 0);
        PlanNodeId planNodeId = new PlanNodeId("1");
        driverContext.addOperatorContext(1, planNodeId, SeriesScanOperator.class.getSimpleName());
        SeriesScanOperator seriesScanOperator = new SeriesScanOperator(driverContext.getOperatorContexts().get(0), planNodeId, measurementPath, allSensors, TSDataType.INT32, null, null, true);
        seriesScanOperator.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        int count = 0;
        while (seriesScanOperator.hasNext()) {
            TsBlock tsBlock = seriesScanOperator.next();
            assertEquals(1, tsBlock.getValueColumnCount());
            assertTrue(tsBlock.getColumn(0) instanceof IntColumn);
            for (int i = 0; i < tsBlock.getPositionCount(); i++, count++) {
                assertEquals(count, tsBlock.getTimeByIndex(i));
                if ((long) count < 200) {
                    assertEquals(20000 + (long) count, tsBlock.getColumn(0).getInt(i));
                } else if ((long) count < 260 || ((long) count >= 300 && (long) count < 380) || (long) count >= 400) {
