        MeasurementPath measurementPath1 = new MeasurementPath(SINGLE_DEVICE_MERGE_OPERATOR_TEST_SG + ".device0.sensor0", TSDataType.INT32);
        MeasurementPath measurementPath2 = new MeasurementPath(SINGLE_DEVICE_MERGE_OPERATOR_TEST_SG + ".device0.sensor1", TSDataType.INT32);
        SeriesScanOperator seriesScanOperator1 = new SeriesScanOperator(driverContext.getOperatorContexts().get(0), planNodeId1, measurementPath1, Collections.singleton("sensor0"), TSDataType.INT32, null, null, true);
        seriesScanOperator1.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator1.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        SeriesScanOperator seriesScanOperator2 = new SeriesScanOperator(driverContext.getOperatorContexts().get(1), planNodeId2, measurementPath2, Collections.singleton("sensor1"), TSDataType.INT32, null, null, true);
        seriesScanOperator2.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator2.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        TimeJoinOperator timeJoinOperator = new TimeJoinOperator(driverContext.getOperatorContexts().get(2), Arrays.asList(seriesScanOperator1, seriesScanOperator2), Ordering.ASC, Arrays.asList(TSDataType.INT32, TSDataType.INT32), Arrays.asList(new SingleColumnMerger(new InputLocation(0, 0), new AscTimeComparator()), new SingleColumnMerger(new InputLocation(1, 0), new AscTimeComparator())), new AscTimeComparator());
        SingleDeviceViewOperator singleDeviceViewOperator = new SingleDeviceViewOperator(driverContext.getOperatorContexts().get(3), SINGLE_DEVICE_MERGE_OPERATOR_TEST_SG + ".device0", timeJoinOperator, Arrays.asList(1, 2), Arrays.asList(TSDataType.TEXT, TSDataType.INT32, TSDataType.INT32, TSDataType.INT32));
