                    assertTrue(tsBlock.getColumn(3).isNull(i));
                }
            }
            count++;
        }
        assertEquals(500, total);
    } catch (IllegalPathException e) {
        e.printStackTrace();
        fail();
    }
}

@Test
public void slidingWindowAggregationTest() throws IllegalPathException {
    String[] retArray = new String[] { "0,100,20049.5,2004950.0,20099,0,99,20000,20099,20000", "50,100,20099.5,2009950.0,20149,50,149,20050,20149,20050", "100,100,20149.5,2014950.0,20199,100,199,20100,20199,20100", "150,100,15199.5,1519950.0,10249,150,249,20150,20199,10200", "200,100,6249.5,624950.0,299,200,299,10200,10259,260", "250,50,2274.5,113725.0,299,250,299,10250,10259,260" };
    SlidingWindowAggregationOperator slidingWindowAggregationOperator1 = initSlidingWindowAggregationOperator(true);
    int count = 0;
    while (slidingWindowAggregationOperator1.hasNext()) {
        TsBlock resultTsBlock = slidingWindowAggregationOperator1.next();
        if (resultTsBlock == null) {
            continue;
        }
        Assert.assertEquals(rootAggregationTypes.size(), resultTsBlock.getValueColumnCount());
        int positionCount = resultTsBlock.getPositionCount();
        for (int pos = 0; pos < positionCount; pos++) {
            Assert.assertEquals(retArray[count], getResultString(resultTsBlock, pos));
            count++;
        }
    }
    Assert.assertEquals(retArray.length, count);
    SlidingWindowAggregationOperator slidingWindowAggregationOperator2 = initSlidingWindowAggregationOperator(false);
    while (slidingWindowAggregationOperator2.hasNext()) {
        TsBlock resultTsBlock = slidingWindowAggregationOperator2.next();
        if (resultTsBlock == null) {
            continue;
        }
        Assert.assertEquals(rootAggregationTypes.size(), resultTsBlock.getValueColumnCount());
        int positionCount = resultTsBlock.getPositionCount();
        for (int pos = 0; pos < positionCount; pos++) {
            Assert.assertEquals(retArray[count - 1], getResultString(resultTsBlock, pos));
            count--;
        }
    }
    Assert.assertEquals(0, count);
}

