        driverContext.addOperatorContext(1, planNodeId1, SeriesAggregationScanOperator.class.getSimpleName());
        PlanNodeId planNodeId2 = new PlanNodeId("2");
        driverContext.addOperatorContext(2, planNodeId2, SeriesAggregationScanOperator.class.getSimpleName());
        driverContext.addOperatorContext(3, new PlanNodeId("3"), VerticallyConcatOperator.class.getSimpleName());
        MeasurementPath measurementPath1 = new MeasurementPath(VERTICALLY_CONCAT_OPERATOR_TEST_SG + ".device0.sensor0", TSDataType.INT32);
        List<AggregationType> aggregationTypes = Arrays.asList(AggregationType.COUNT, AggregationType.SUM, AggregationType.FIRST_VALUE);
        GroupByTimeParameter groupByTimeParameter = new GroupByTimeParameter(0, 10, 1, 1, true);
        List<Aggregator> aggregators = new ArrayList<>();
        AccumulatorFactory.createAccumulators(aggregationTypes, TSDataType.INT32, true).forEach(o -> aggregators.add(new Aggregator(o, AggregationStep.SINGLE)));
        SeriesAggregationScanOperator seriesAggregationScanOperator1 = new SeriesAggregationScanOperator(planNodeId1, measurementPath1, allSensors, driverContext.getOperatorContexts().get(0), aggregators, initTimeRangeIterator(groupByTimeParameter, true, true), null, true, groupByTimeParameter, DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES);
        seriesAggregationScanOperator1.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesAggregationScanOperator1.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        MeasurementPath measurementPath2 = new MeasurementPath(VERTICALLY_CONCAT_OPERATOR_TEST_SG + ".device0.sensor1", TSDataType.INT32);
        SeriesAggregationScanOperator seriesAggregationScanOperator2 = new SeriesAggregationScanOperator(planNodeId2, measurementPath2, allSensors, driverContext.getOperatorContexts().get(1), aggregators, initTimeRangeIterator(groupByTimeParameter, true, true), null, true, groupByTimeParameter, DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES);
        seriesAggregationScanOperator2.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesAggregationScanOperator2.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        VerticallyConcatOperator verticallyConcatOperator = new VerticallyConcatOperator(driverContext.getOperatorContexts().get(2), Arrays.asList(seriesAggregationScanOperator1, seriesAggregationScanOperator2), Arrays.asList(TSDataType.INT64, TSDataType.DOUBLE, TSDataType.INT32, TSDataType.INT64, TSDataType.DOUBLE, TSDataType.INT32));
        int count = 0;
        while (verticallyConcatOperator.hasNext()) {
            TsBlock tsBlock = verticallyConcatOperator.next();
            assertEquals(6, tsBlock.getValueColumnCount());
            for (int i = 0; i < tsBlock.getPositionCount(); i++, count++) {
                assertEquals(count, tsBlock.getTimeByIndex(i));
                assertEquals(1, tsBlock.getColumn(0).getLong(i));
                assertEquals(20000 + count, tsBlock.getColumn(1).getDouble(i), 0.00001);
                assertEquals(20000 + count, tsBlock.getColumn(2).getInt(i));
                assertEquals(1, tsBlock.getColumn(3).getLong(i));
                assertEquals(20000 + count, tsBlock.getColumn(4).getDouble(i), 0.00001);
                assertEquals(20000 + count, tsBlock.getColumn(5).getInt(i));
            }
        }
        assertEquals(10, count);
    } catch (IllegalPathException e) {
        e.printStackTrace();
        fail();
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

@Test
public void TestBasicTransition() {
    QueryStateMachine stateMachine = genQueryStateMachine();
    Assert.assertEquals(stateMachine.getState(), QueryState.QUEUED);
    stateMachine.transitionToDispatching();
    Assert.assertEquals(stateMachine.getState(), QueryState.DISPATCHING);
    stateMachine.transitionToRunning();
    Assert.assertEquals(stateMachine.getState(), QueryState.RUNNING);
    stateMachine.transitionToAborted();
    Assert.assertEquals(stateMachine.getState(), QueryState.ABORTED);
    // StateMachine with Terminal State is not allowed to transition state
    stateMachine = genQueryStateMachine();
    stateMachine.transitionToCanceled();
    Assert.assertEquals(stateMachine.getState(), QueryState.CANCELED);
    stateMachine = genQueryStateMachine();
    stateMachine.transitionToFinished();
    Assert.assertEquals(stateMachine.getState(), QueryState.FINISHED);
}

@Test
public void TestListener() throws ExecutionException, InterruptedException {
    AtomicInteger stateChangeCounter = new AtomicInteger(0);
    QueryStateMachine stateMachine = genQueryStateMachine();
    stateMachine.addStateChangeListener(state -> {
        stateChangeCounter.getAndIncrement();
    });
    stateMachine.transitionToFinished();
    SettableFuture<QueryState> future = SettableFuture.create();
    stateMachine.addStateChangeListener(state -> {
        if (state == QueryState.FINISHED) {
            future.set(QueryState.FINISHED);
        }
    });
    future.get();
    Assert.assertEquals(stateChangeCounter.get(), 2);
}

@Test
public void TestGetStateChange() throws ExecutionException, InterruptedException {
    AtomicInteger stateChangeCounter = new AtomicInteger(0);
    QueryStateMachine stateMachine = genQueryStateMachine();
    SettableFuture<Void> callbackFuture = SettableFuture.create();
    ListenableFuture<QueryState> future = stateMachine.getStateChange(QueryState.QUEUED);
    future.addListener(() -> {
        stateChangeCounter.getAndIncrement();
        callbackFuture.set(null);
    }, directExecutor());
    Assert.assertEquals(stateChangeCounter.get(), 0);
    stateMachine.transitionToRunning();
    future.get();
    callbackFuture.get();
    Assert.assertEquals(stateChangeCounter.get(), 1);
}

