@Test
public void testPollBlocked() throws InterruptedException {
    IndexedBlockingQueue<QueueElement> queue = new L2PriorityQueue<>(10, (o1, o2) -> {
        if (o1.equals(o2)) {
            return 0;
        }
        return Integer.compare(o1.getValue(), o2.getValue());
    }, new QueueElement(new QueueElement.QueueElementID(0), 0));
    List<QueueElement> res = new ArrayList<>();
    Thread t1 = new Thread(() -> {
        try {
            QueueElement e = queue.poll();
            res.add(e);
        } catch (InterruptedException e) {
            e.printStackTrace();
            fail();
        }
    });
    t1.start();
    await().atMost(1, TimeUnit.MINUTES).untilAsserted(() -> Assert.assertEquals(Thread.State.WAITING, t1.getState()));
    QueueElement e2 = new QueueElement(new QueueElement.QueueElementID(1), 1);
    queue.push(e2);
    await().atMost(1, TimeUnit.MINUTES).untilAsserted(() -> Assert.assertEquals(Thread.State.TERMINATED, t1.getState()));
    Assert.assertEquals(1, res.size());
    Assert.assertEquals(e2.getDriverTaskId().toString(), res.get(0).getDriverTaskId().toString());
}

