    assertAnalyzeSemanticException("select s1, s2 into root.sg_bk.new_d(t1, t2), aligned root.sg_bk.new_d(t3, t4) from root.sg.*;", DEVICE_ALIGNMENT_INCONSISTENT_ERROR_MSG);
    assertAnalyzeSemanticException("select count(s1), last_value(s2) into root.sg_bk.new_${2}(::) from root.sg.* align by device;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select count(s1), last_value(s2) into root.sg_bk.new_d1(::), root.sg_bk.new_d2(::) from root.sg.* align by device;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select count(s1), last_value(s2) into root.sg_bk.new_d1(::), root.sg_bk.new_d2(::) from root.sg.*;", FORBID_PLACEHOLDER_ERROR_MSG);
