    assertAnalyzeSemanticException("select s1 + 1, s1 + s2 into root.sg_bk.new_${2}(::) from root.sg.* align by device;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select s1 + 1, s1 + s2 into root.sg_bk.new_d1(::), root.sg_bk.new_d2(::) from root.sg.* align by device;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select s1 + 1, s1 + s2 into root.sg_bk.new_d1(::), root.sg_bk.new_d2(::) from root.sg.*;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select s1 + 1, s1 + s2 into root.sg_bk.new_${2}(t1, t2, t3, t4) from root.sg.*;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select s1 + 1, s1 + s2 into root.sg_bk.new_${2}(::) from root.sg.*;", FORBID_PLACEHOLDER_ERROR_MSG);
    assertAnalyzeSemanticException("select * into root.sg_bk.new_d1(::), root.sg_bk.new_d2(::) from root.sg.**;", PLACEHOLDER_MISMATCH_ERROR_MSG);
    assertAnalyzeSemanticException("select s1, s2 into root.sg_bk.new_d1(${3}, s2) from root.sg.d1;", PLACEHOLDER_MISMATCH_ERROR_MSG);
    assertAnalyzeSemanticException("select * into root.sg_bk.new_${2}(::, s1) from root.sg.**;", PLACEHOLDER_MISMATCH_ERROR_MSG);
    assertAnalyzeSemanticException("select d1.s1, d1.s2, d2.s3, d3.s4 into ::(s1_1, s2_2, backup_${4}) from root.sg", PLACEHOLDER_MISMATCH_ERROR_MSG);
    assertAnalyzeSemanticException("select s1, s2 into ::(s1_1, s2_2), root.backup_sg.::(s1, s2) from root.sg.* align by device;", PLACEHOLDER_MISMATCH_ERROR_MSG);
}

