@Test
public void testConcurrentTake() throws InterruptedException {
    final FixedPriorityBlockingQueue<Integer> testQueue = new FixedPriorityBlockingQueue<>(100, Integer::compare);
    Random random = new Random(10);
    List<Integer> resultList = new ArrayList<>();
    ReentrantLock lock = new ReentrantLock();
    List<Integer> expectedList = new ArrayList<>();
    for (int i = 0; i < 90; ++i) {
        int curr = random.nextInt();
        testQueue.put(curr);
        expectedList.add(curr);
    }
    Collections.sort(expectedList);
    Thread t1 = new Thread(() -> {
        try {
            while (resultList.size() < 90) {
                lock.lock();
                try {
                    if (resultList.size() >= 90) {
                        return;
                    }
                    int curr = testQueue.take();
                    resultList.add(curr);
                } finally {
                    lock.unlock();
                }
            }
        } catch (InterruptedException e) {
        }
    });
    Thread t2 = new Thread(() -> {
        try {
            while (resultList.size() < 90) {
                lock.lock();
                try {
                    if (resultList.size() >= 90) {
                        return;
                    }
                    int curr = testQueue.take();
                    resultList.add(curr);
                } finally {
                    lock.unlock();
                }
            }
        } catch (InterruptedException e) {
        }
    });
    Thread t3 = new Thread(() -> {
        try {
            while (resultList.size() < 90) {
                lock.lock();
                try {
                    if (resultList.size() >= 90) {
                        return;
                    }
                    int curr = testQueue.take();
                    resultList.add(curr);
                } finally {
                    lock.unlock();
                }
            }
        } catch (InterruptedException e) {
        }
    });
    t1.start();
    t2.start();
    t3.start();
    t1.join();
    t2.join();
    t3.join();
    Assert.assertArrayEquals(expectedList.toArray(new Integer[0]), resultList.toArray(new Integer[0]));
}

@Test
public void testHooks() throws InterruptedException {
    List<AtomicInteger> integers = new ArrayList<>();
    Random random = new Random(100);
    FixedPriorityBlockingQueue<AtomicInteger> testQueue = new FixedPriorityBlockingQueue<>(10, Comparator.comparingInt(AtomicInteger::get));
    for (int i = 0; i < 20; ++i) {
        integers.add(new AtomicInteger(random.nextInt(1000)));
    }
    testQueue.regsitPollLastHook(x -> x.set(x.get() + 1));
    testQueue.regsitPollLastHook(x -> x.set(x.get() * 5));
    testQueue.regsitPollLastHook(x -> x.set(x.get() * x.get()));
    integers.sort(Comparator.comparingInt(AtomicInteger::get));
    List<AtomicInteger> expectedList = new ArrayList<>();
    List<AtomicInteger> tempList = integers.subList(10, 20);
    for (AtomicInteger i : tempList) {
        expectedList.add(new AtomicInteger(i.get()));
    }
    for (AtomicInteger atomicInteger : integers) {
        testQueue.put(atomicInteger);
    }
    expectedList.forEach(x -> x.set(x.get() + 1));
    expectedList.forEach(x -> x.set(x.get() * 5));
    expectedList.forEach(x -> x.set(x.get() * x.get()));
    for (int i = 0; i < expectedList.size(); ++i) {
        Assert.assertEquals(expectedList.get(i).get(), tempList.get(i).get());
    }
}

