            IWALNode walNode = elasticStrategy.applyForWALNode(String.valueOf(i));
            if (i % ElasticStrategy.APPLICATION_NODE_RATIO == 0) {
                walNodes[i / ElasticStrategy.APPLICATION_NODE_RATIO] = walNode;
