public void showTimeseriesTagsTest() throws SQLException {
    String createTimeSeries1 = "create timeseries root.ln.wf01.wt1 WITH DATATYPE=DOUBLE, ENCODING=RLE, compression=SNAPPY tags(tag1=v1, tag2=v2)";
    String createTimeSeries2 = "create timeseries root.ln.wf01.wt2 WITH DATATYPE=DOUBLE, ENCODING=RLE, compression=SNAPPY tags(tag1=v1, tag2=v2)";
    writeStatement.execute(createTimeSeries1);
    writeStatement.execute(createTimeSeries2);
    // try to read data on each node. select .*
    for (Statement readStatement : readStatements) {
        ResultSet resultSet = readStatement.executeQuery("SHOW TIMESERIES root.ln.wf01.* where tag1=v1");
        int cnt = 0;
        while (resultSet.next()) {
            cnt++;
        }
        Assert.assertEquals(2, cnt);
        resultSet.close();
    }
    // try to read data on each node. select from parent series
    for (Statement readStatement : readStatements) {
        ResultSet resultSet = readStatement.executeQuery("SHOW TIMESERIES root.ln.wf01.* where tag1=v1");
        int cnt = 0;
        while (resultSet.next()) {
            cnt++;
        }
        Assert.assertEquals(2, cnt);
        resultSet.close();
    }
    // try to read data on each node. select from one series
    for (Statement readStatement : readStatements) {
        ResultSet resultSet = readStatement.executeQuery("SHOW TIMESERIES root.ln.wf01.wt1 where tag1=v1");
        int cnt = 0;
        while (resultSet.next()) {
            cnt++;
        }
        Assert.assertEquals(1, cnt);
        resultSet.close();
    }
    // try to read data on each node. select from root
    for (Statement readStatement : readStatements) {
        ResultSet resultSet = readStatement.executeQuery("SHOW TIMESERIES root.** where tag1=v1");
        int cnt = 0;
        while (resultSet.next()) {
            cnt++;
        }
        Assert.assertEquals(2, cnt);
        resultSet.close();
    }
    // try to read data on each node. SHOW TIMESERIES root.ln.wf01.* where tag1=v3"
    for (Statement readStatement : readStatements) {
        ResultSet resultSet = readStatement.executeQuery("SHOW TIMESERIES root.ln.wf01.* where tag1=v3");
        int cnt = 0;
        while (resultSet.next()) {
            cnt++;
        }
        Assert.assertEquals(0, cnt);
        resultSet.close();
    }
    // try to read data on each node. SHOW TIMESERIES root.ln.wf01.* where tag3=v1"
    for (Statement readStatement : readStatements) {
        try (ResultSet rs = readStatement.executeQuery("SHOW TIMESERIES root.ln.wf01.* where tag3=v1")) {
            Assert.assertFalse(rs.next());
        }
    }
}

@Test
public void clusterUDTFQueryTest() throws SQLException {
    // Prepare data.
    writeStatement.execute("CREATE timeseries root.sg.d.s WITH datatype=DOUBLE, encoding=RLE, compression=SNAPPY");
    for (int i = 10; i < 20; i++) {
        writeStatement.execute(String.format("INSERT INTO root.sg.d(timestamp,s) VALUES(%s,%s)", i, i));
    }
    for (int i = 0; i < 10; i++) {
        writeStatement.execute(String.format("INSERT INTO root.sg.d(timestamp,s) VALUES(%s,%s)", i, i));
    }
    ResultSet resultSet = null;
    // Try to execute udf query on each node.
    // Without time filter
    for (Statement readStatement : readStatements) {
        resultSet = readStatement.executeQuery("SELECT sin(s) FROM root.sg.d");
        double i = 0;
        while (resultSet.next()) {
            Assert.assertEquals(Math.sin(i++), resultSet.getDouble(2), 0.00001);
        }
        Assert.assertFalse(resultSet.next());
        resultSet.close();
    }
    // With time filter
    for (Statement readStatement : readStatements) {
        resultSet = readStatement.executeQuery("SELECT sin(s) FROM root.sg.d WHERE time >= 5");
        double i = 5;
        while (resultSet.next()) {
            Assert.assertEquals(Math.sin(i++), resultSet.getDouble(2), 0.00001);
        }
        Assert.assertFalse(resultSet.next());
        resultSet.close();
    }
}

@Test
public void testSelectInto() throws SQLException {
    for (int i = 0; i < 10; i++) {
        writeStatement.execute(String.format("CREATE timeseries root.sg.device%s.s WITH datatype=DOUBLE, encoding=RLE, compression=SNAPPY", i));
        writeStatement.execute(String.format("CREATE timeseries root.sg.device%s.t WITH datatype=DOUBLE, encoding=RLE, compression=SNAPPY", i));
        writeStatement.execute(String.format("INSERT INTO root.sg.device%s(timestamp,s) VALUES(1,1)", i));
    }
    writeStatement.execute("SELECT device0.s, device1.s, device2.s, device3.s, device4.s, device5.s, device6.s, device7.s, device8.s, device9.s " + "INTO device0.t, device1.t, device2.t, device3.t, device4.t, device5.t, device6.t, device7.t, device8.t, device9.t " + "FROM root.sg;");
    for (int i = 0; i < 10; i++) {
        writeStatement.execute(String.format("INSERT INTO root.sg.device%s(timestamp,s) VALUES(2,2)", i));
        writeStatement.execute(String.format("SELECT device%s.s into device%s.t from root.sg;", i, i));
    }
    for (Statement readStatement : readStatements) {
        for (int i = 0; i < 10; ++i) {
            try (ResultSet resultSet = readStatement.executeQuery(String.format("SELECT s, t FROM root.sg.device%s", i))) {
                Assert.assertTrue(resultSet.next());
                Assert.assertEquals(1, Double.parseDouble(resultSet.getString(1)), 0);
                Assert.assertEquals(Double.parseDouble(resultSet.getString(1)), Double.parseDouble(resultSet.getString(2)), 0);
                Assert.assertEquals(Double.parseDouble(resultSet.getString(2)), Double.parseDouble(resultSet.getString(3)), 0);
                Assert.assertTrue(resultSet.next());
                Assert.assertEquals(2, Double.parseDouble(resultSet.getString(1)), 0);
                Assert.assertEquals(Double.parseDouble(resultSet.getString(1)), Double.parseDouble(resultSet.getString(2)), 0);
                Assert.assertEquals(Double.parseDouble(resultSet.getString(2)), Double.parseDouble(resultSet.getString(3)), 0);
                Assert.assertFalse(resultSet.next());
            }
        }
    }
}

@Test
public void SetSystemReadOnlyWritableTest() throws SQLException {
    String setReadOnly = "SET SYSTEM TO READONLY";
    String createTimeSeries = "create timeseries root.ln.wf01.wt1 WITH DATATYPE=DOUBLE, ENCODING=RLE, compression=SNAPPY tags(tag1=v1, tag2=v2)";
    String setWritable = "SET SYSTEM TO WRITABLE";
    writeStatement.execute(setReadOnly);
    try {
        writeStatement.execute(createTimeSeries);
    } catch (Exception e) {
        Assert.assertTrue(e.getMessage().contains("Database is read-only, and does not accept non-query operation now"));
    }
    writeStatement.execute(setWritable);
}

