    ArrayList<Integer> preValues = new ArrayList<Integer>();
    IntPacker packer = new IntPacker(width);
    byte[] bb = new byte[count * width];
    int idx = 0;
    for (int i = 0; i < count; i++) {
        int[] vs = new int[8];
        for (int j = 0; j < 8; j++) {
            vs[j] = rand.nextInt(Integer.MAX_VALUE);
